quests[61394] = { id = 61394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormlingwerfen: Ruhige Teiche" }
quests[61395] = { id = 61395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile" }
quests[61396] = { id = 61396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Entwicklungen", description = "<Das zerfledderte Dokument scheint von Chirurg Fleischnaht aufgesetzt worden zu sein.>\n\n... kyrianisches Fleisch verbessert Stärke, Gehorsam und Geschicklichkeit doppelt! Was für ein Potenzial!\n\nWenn jetzt bei Versuchsobjekt eins-drei-fünf endlich die Schwingentransplantation klappt...\n\n<So geht es eine Weile weiter. Ihr solltet es zu Euren kyrianischen Verbündeten bringen.>", sourceObjective = "Bringt den abscheulichen Entwurf zu Artemede.\n\nBereitgestellter Gegenstand:", completion = "Gewährt mir einen Moment, um das zu lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61397] = { id = 61397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gelegenheit bietet sich", description = "Dieses Sanktum kann nicht allein mit Anima funktionieren. Es bedarf vieler williger Seelen, die in Harmonie zusammenarbeiten, um das volle Potenzial des Sitzes des Primus zu erschließen.\n\nUnser Seelenwächter ist immer auf der Suche nach neuen Seelen, die er in das Sanktum einführen kann. Eure Fähigkeit, vom Schlund aus hin und her zu reisen, wird sich zweifellos als nützlich für ihn erweisen.\n\nIhr solltet ihm einen Besuch abstatten, um zu sehen, welche Hilfe Ihr anbieten könnt.", sourceObjective = "Sprecht mit Osbourne Black.", completion = "Mit Euren einzigartigen Fähigkeiten haben wir eine Gelegenheit, die sich uns noch nie zuvor geboten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[61398] = { id = 61398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Traditionell", description = "Natürlich ist es Dunkelhafen eine Ehre, traditionelle Dekorationen für Prinz Renathals Hof zur Verfügung zu stellen.\n\nBei Venthyrdekorationen kommt es vor allem auf die richtige Stimmung an. Das heißt: lauernde Steinunholde und nach Todesblüte duftende Kerzen in rauen Mengen.\n\nAber unsere Ressourcen haben sich sehr erschöpft, {name}. Steinunholde sind kein Problem, aber unsere Kunsthandwerker benötigen Wachs, um es mit frischen Todesblüten zu verschmelzen. Im Dorf sollte es genügend Wachsreste und Kerzenstümpfe geben. Die Todesblüten erhaltet ihr von den Pflanzen selbst.", sourceObjective = "Sammelt 50 Einheiten Kerzenwachs und 20 Todesblüten. Todesblüten können mithilfe der Kräuterkundefertigkeit geerntet werden.", progress = "Habt Ihr schon das Rohmaterial für unsere Kunsthandwerker besorgt?", completion = "Dann machen wir uns besser gleich an die Arbeit. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61399] = { id = 61399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Erinnerungen an die Sterblichkeit", description = "Gegen eine entsprechende Entlohnung kann Euch Kartell Ta die gewünschten Dekorationen besorgen.\n\nDas Lager mit einzigartigen und faszinierenden Objekten zu füllen, ist ein wichtiger Teil des Geschäfts. Da Ihr jederzeit in Eure Welt zurückkehren könnt, besorgt mir doch einige neue und aufregende Produkte für mein Angebot.\n\nViele unserer Kunden sind fasziniert von Eurer Welt. Ich kenne ein paar Käufer, die insbesondere an speziellen Waren aus Azeroth Interesse haben.", sourceObjective = "Helft Hüter Ta'saran, das Lager aufzufüllen, indem Ihr die Sachen auf der Liste besorgt, die er Euch gegeben hat.", progress = "Habt Ihr etwas Passendes für jeden Punkt auf der Liste gefunden?", completion = "Ja, ja. Ganz ausgezeichnete Arbeit. Unsere Kunden werden begeistert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61400] = { id = 61400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Mysteriöse Spiegel", description = "Ich unterstütze Prinz Renathals Bemühungen und werde gewiss beim Gluthof helfen!\n\nMysteriöse Spiegel sind gefährlich, aber bringen Stimmung in jedes Fest. Ich brauche aber eine Menge Spiegelfragmente, damit genug davon noch rechtzeitig fertig werden.\n\nIhr werdet auch meinen Vorrat an Aschekernen auffrischen müssen, damit ich das Glas ausreichend schmelzen kann, um es zu verarbeiten.", sourceObjective = "Sammelt 12 verhüllte Spiegelscherben, 12 versengte Spiegelfragmente und 3 geschmolzene Kerne.", progress = "Habt Ihr die Spiegelfragmente und einen Aschekern gefunden?", completion = "Danke, dass Ihr die notwendigen Zutaten für die Herstellung der Spiegel gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[61401] = { id = 61401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Freiwillige Venthyr", description = "Oh, hallo mal wieder!\n\nHabt Ihr schon gehört, dass mir der Befehl über die Wache beim Gluthof anvertraut wurde? Das wäre natürlich noch beeindruckender, wenn wir schon ein paar Rekruten hätten.\n\nIch muss diese Rekrutierungsposter aufhängen lassen. Wenn Ihr Euch darum kümmern könntet, würde ich die interessierten Rekruten hier versammeln, damit wir bei Eurer Rückkehr ihre Kampffähigkeiten testen können.", sourceObjective = "Platziert 6 Rekrutierungsplakate und testet 3 Rekruten von Sündensturz.", completion = "Haha! Das könnte ein schöner Spaß werden. Ich übernehme die Tests mit den verbleibenden Rekruten!", sourceObjectiveStatus = "unverified-source-field" }
quests[61402] = { id = 61402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Steingeborene Reservisten", description = "Um die Reserven für die Sicherheit am Gluthof zu mobilisieren, brauchen wir Anima. Gute, loyale Truppen stehen bereit, sobald wir sie animieren können.\n\nAußerdem brauchen wir noch Waffen für sie.\n\nKümmert Euch darum und ich sorge dafür, dass der Prinz und seine Gäste gut beschützt werden.", sourceObjective = "Füllt den Animakanister, indem Ihr gegnerische Steingeborene in der Herrschaftsburg besiegt. Sammelt 12 Steingeborenengleven.", progress = "Habt ihr den Animakanister gefüllt und genügend Waffen für unsere neuen Kameraden gefunden?", completion = "Gut. Das sollte reichen, damit ich die Reserve mobilisieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[61403] = { id = 61403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Armee von Maldraxxus", description = "Die kleinen Feiern Eures Prinzen haben also unerwünschte Aufmerksamkeit erregt?\n\n<Emeni lacht.>\n\nIch pflege eine lange Liste meiner Feinde und viel zu viele von ihnen verbergen sich im Lande der Lebenden. Feiglinge!\n\nAber ich habe endlich eine Lösung gefunden.\n\nBringt diesen Kristall zu meinen Überresten nach Azeroth und verwendet ihn, um mein Abbild für kurze Zeit auf die Lebenden zu übertragen, damit ich Rache an meiner alten Sippschaft nehmen kann.", sourceObjective = "Entfesselt Emenis Projektion in Vol'dun und helft ihr, ihre alten Sethrakfeinde zu besiegen.", completion = "So ein Gemetzel... So viele Namen von meiner Liste gestrichen...\n\nEine ganze neue Generation an Sethrak wird meinen Namen fürchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[61404] = { id = 61404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Tubbins' Teekränzchen", description = "Theotar braucht Tee für Fest? Tubbins hat den Besten!\n\nBesonderer Tee. Ganz besonders. Kenne nur ich. Geht aber nur mit echt gutem Wasser aus Garten. Guter Teich auf ganz besonderer Schwebeinsel!\n\nIhr geht und holt. Dann Tubbins macht Tee!", sourceObjective = "Sammelt unberührtes Wasser aus der Abgelegenen Grotte im Ardenwald.", progress = "Brauche besonderes Wasser für besonderen Tee. Leuchtet ein.", completion = "Mmm, Wasser schmeckt sauber...\n\nWie ich! Ich bin am saubersten!", sourceObjectiveStatus = "unverified-source-field" }
quests[61405] = { id = 61405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Deliziöse Desserts", description = "Rezepte sehr wichtig! Niemals verlieren!\n\nViele Gerichte in meinem Buch. Gelernt von Sterblichen. Was gut, was schlecht? Immer probieren. Einziger Weg. Sicher ist sicher. Ihr zeigt mir neues Rezept? Bringt mir Zutaten? Dann koche ich nach. Probiere Eures, probiere meins. Hilft mir lernen.\n\nIch bringe Desserts für Gluthof.\n\nFair, ja?", sourceObjective = "Sammelt eine Probe von Bananenpudding mit Rind, 30 Stücke ätherisches Fleisch und 20 Phantasmakeulen. Probiert dann Supis Gericht.", progress = "Ihr habt alles? Und bereit für Kostprobe?", completion = "Was einfach aussieht, immer schwierig. Jede Zutat muss perfekt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[61406] = { id = 61406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Pilz Surprise", description = "Ich hatte keine Ahnung, dass meine berühmten Pilze sich so herumsprechen. Es wäre mir eine Freude, ein Pilzfestmahl für den Gluthof zu kochen!\n\nHmmm... Ihr müsst mir ein paar seltene Exemplare besorgen. Dafür leihe ich Euch meinen liebsten Sammelbeutel, mit dem Ihr die besten Pilze finden könnt. Das funktioniert wirklich immer.\n\nMal sehen, ich brauche kleine Geflechtkäppchen aus der Bastion und ein paar der ausgefallenen Violettkäppchen aus dem Ardenwald. Und von den Spitzen unserer Pilze hier brauche ich Federkappen. Ihr müsst wohl ganz bis nach oben klettern.", sourceObjective = "Sammelt 18 Federkappen, 24 Flechthutmorcheln und 4 Violettkäppchen.", progress = "Habt Ihr den Sammelbeutel gefüllt?", completion = "Hm, die duften wunderbar und reif! Dafür habt Ihr wirklich ein Händchen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61407] = { id = 61407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Rituale der Buße", description = "Wenn Prinz Renathal seinen Gästen wirklich etwas von dem Wissen der höchsten Berufung in ganz Revendreth vermitteln will, wäre es uns eine Ehre, die Rituale der Sühne zu demonstrieren.\n\nIch muss Euch allerdings bitten, mir bei der Vorbereitung der wichtigsten Komponenten etwas zur Hand zu gehen.\n\nFangt ein paar flüchtige Seelen, die sich in der Nähe vor den korrupten Venthyr des Obersten Kämmerers verstecken. Bringt sie zu unseren eingeschworenen Ritualisten am anderen Ende der Hallen. Sie werden die Seelen für unsere Zwecke vorbereiten.\n\nSündensteinfragmente würden uns ebenfalls helfen, die Sünden dieser verlorenen Seelen zu identifizieren.", sourceObjective = "Sammelt 125 Sündensteinfragmente und bringt 2 flüchtige Seelen zu eingeschworenen Ritualisten.", progress = "Flüchtige Seelen verstecken sich in den dunkelsten Ecken der Hallen der Sühne.", completion = "Danke, {name}. Die Anklägerin und ich werden die Rituale am Gluthof persönlich durchführen.\n\nWir werden alle an die wahre Bestimmung von Revendreth erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[61408] = { id = 61408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Blick in die Wildnis", description = "Es wäre wunderbar, Revendreth die wilden Kreaturen aus dem Ardenwald vorzuführen!\n\nIhr findet strahlende Barsche bei den Wasserfällen. Sie sind ziemlich flink. Ihr müsst sie einfach packen, wenn sie vorbeischwimmen.\n\nHier ist ein Netz, um die territorialen Water zu unterwerfen. Wenn Ihr sie erst gefangen habt, sollten sie Euch folgen.\n\nHochlandrunenhirsche lassen sich von Euch reiten, wenn Ihr nicht zu aggressiv vorgeht. Bringt mir bitte ein paar von ihnen her. Passt bei den Bullen auf, die sind nicht gerade freundlich.\n\nWir fragen auch die anderen, ob sie uns helfen. Das klingt lustig.", sourceObjective = "Bringt 3 Hochlandrunenhirsche, 8 strahlende Barsche und 4 unterworfene territoriale Water zu Niya.", progress = "Wir brauchen strahlende Barsche, Hochlandrunenhirsche und territoriale Water, bitte.", completion = "Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61411] = { id = 61411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwie, irgendwo, irgendwann" }
quests[61412] = { id = 61412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein jähes Ende", description = "In der Halle der Ketten warten noch mehr Konstrukte, die fast vollendet sind. In diesem Moment arbeiten die Truppen des Markgrafen fieberhaft daran, die letzten Stücke Fleisch an ihre scheußlichen Visagen zu transplantieren.\n\nStellen sie ihre Arbeit fertig, wird die von uns verursachte Zerstörung in der letzten Schlacht nur wenig Unterschied machen. Unsere Flanke wird von einer neuen Welle des Schreckens überrannt, und die Schlacht ist verloren.\n\nDas darf nicht passieren. Zerstört alle Monstrositäten, denen Ihr begegnet.", sourceObjective = "Zerstört 6 unbelebte Schlächter.", completion = "Jede unvollendete Monstrosität ist ein Gegner weniger, wenn wir Gharmal gegenüber stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61414] = { id = 61414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlerhaftes Feuerwerk (+Sicher)", progress = "<Prinz Renathal betrachtet besorgt das fehlerhafte Feuerwerk, das Ihr mitgebracht habt.>\n\nDiese minderwertige Partyunterhaltung könnte ganz Sündensturz in Flammen aufgehen lassen!", completion = "Ich weiß wirklich zu schätzen, dass Ihr mir dieses Feuerwerk bringt, {name}.\n\nFür solch minderwertige Aufmerksamkeiten ist auf unserem Fest kein Platz." }
quests[61421] = { id = 61421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Wonnenschwinge", sourceObjective = "Ihr habt sowohl Enothia als auch mich gerettet. Um mich für Eure Güte zu revanchieren, würde ich Euch gern auf Eurem Abenteuer begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61422] = { id = 61422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Dämmerblatt", sourceObjective = "Endlich ist der Rache Genüge getan. Oder der Gerechtigkeit? Auf jeden Fall genügt es mir. Vielleicht kann ich Euch jetzt einen Dienst erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61423] = { id = 61423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Karynmwylyann", sourceObjective = "Meine Erinnerungen sind wieder da und jetzt brauche ich einen neuen Pfad. Wenn Ihr wünscht, begleite ich Euch gern ein Stück weit auf Eurem.", sourceObjectiveStatus = "unverified-source-field" }
quests[61424] = { id = 61424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Chalkyth", sourceObjective = "Gestattet mir und meinem Säbel, Eure Feinde ein weiteres Mal zu vertrimmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[61425] = { id = 61425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lloth'wellyn", sourceObjective = "Danke für Eure Hilfe. Ich habe sie vermerkt. Ich glaube auch, dass ich Euch weiterhelfen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[61426] = { id = 61426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Yira'lya", sourceObjective = "Bringt mich bitte zurück in den Ardenwald. Von hier aus kann ich nichts tun, um Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61427] = { id = 61427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wonnenschwinges Rettung" }
quests[61428] = { id = 61428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerblatts Rache" }
quests[61429] = { id = 61429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynmwylyanns Wurzeln" }
quests[61430] = { id = 61430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chalkyths Säbel" }
quests[61431] = { id = 61431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lloth'wellyns Durchbruch" }
quests[61432] = { id = 61432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Tagebücher", progress = "Was habt Ihr denn da gefunden?", completion = "Ich erkenne diese Handschrift, sind das wirklich die Seiten des Prinzen? Ich werde dafür sorgen, dass sie nach Sündensturz gelangen. Der Hof ist dankbar, dass Ihr sie zurückgebracht habt." }
quests[61433] = { id = 61433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenlungenkappe", progress = "Ist das... eine Lungenkappe?\n\nWie konntet Ihr hier in Revendreth eine finden?\n\nEinerlei. Werft sie auf einen Teller!\n\nVielleicht bemerken sie nicht, wie schrecklich sie schmeckt.", completion = "Was ihr an Geschmack fehlt, macht sie an Größe wieder wett.\n\nIch sollte damit drei Teller füllen können, wenn ich sie richtig aufschneide." }
quests[61434] = { id = 61434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemie: Fläschchen der bemessenen Disziplin" }
quests[61435] = { id = 61435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunst: Pirscherpfeilspitzen" }
quests[61436] = { id = 61436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exkursion", description = "Nachdem Ihr jetzt den Katalysator habt, müsst Ihr ihn nur noch zu Mortimer nach Maldraxxus bringen. In seinem letzten Brief stand, dass sein Labor im ehemaligen Haus der Seuchen immer noch intakt ist.\n\nSeid unterwegs vorsichtig. Was von dem Haus noch übrig ist, birgt eine Menge Gefahren, und Mortimer selbst genießt unter seinesgleichen nicht gerade den besten Ruf.", sourceObjective = "Bringt den Katalysator der Schöpfung zum Manischen Mortimer im Haus der Seuchen in Maldraxxus.\n\nBereitgestellter Gegenstand:", completion = "Ah, ja! Ihr kommt wohl aus der Bastion! Wunderbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[61439] = { id = 61439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst: Provosteneintopf" }
quests[61440] = { id = 61440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberkunst: Korb der Fülle" }
quests[61441] = { id = 61441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingenieurskunst: Servohammer" }
quests[61442] = { id = 61442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln: Prächtige Schimmerflosse" }
quests[61443] = { id = 61443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde: Windgepeitschter Ruhmesstieg" }
quests[61445] = { id = 61445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoftratsch (+Entspannt)", progress = "<Prinz Renathal streckt mit hoch erhobenem Kopf einen Arm aus.>\n\nDas nehme ich Euch ab.", completion = "Dieser Hof ist nicht der richtige Ort für nutzlosen Tratsch. Ich werde diese Schriftrolle auf der Stelle wegwerfen!" }
quests[61446] = { id = 61446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inschriftenkunde: Anrufung der Pflicht" }
quests[61447] = { id = 61447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelierskunst: Schimmernde Kyranithalskette" }
quests[61448] = { id = 61448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleimklumpen (+Sauber)", progress = "<Prinz Renathal lehnt sich zurück, wendet sich ab und streckt einen Arm aus.>\n\nDieser Schund muss auf der Stelle entsorgt werden!", completion = "Danke für Eure Bemühungen, unseren Hof so makellos zu halten, wie er sein sollte." }
quests[61449] = { id = 61449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lederverarbeitung: Stahlhautlederharnisch" }
quests[61450] = { id = 61450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samenbündel (+Bescheiden)", progress = "Was haben wir denn hier? Eine Auswahl von Samen?", completion = "Obgleich sie nicht für ihr Aroma bekannt sind, bin ich sicher, dass diese Häppchen einen der anwesenden wählerischen Gaumen zufriedenstellen werden." }
quests[61467] = { id = 61467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergbau: Strahlendes Soleniumerz" }
quests[61468] = { id = 61468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürschnerei: Luxuriöses Kupferpelzfell" }
quests[61469] = { id = 61469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneiderei: Gespinstgewebetunika" }
quests[61473] = { id = 61473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschafft Euch Eure eigenen Materialien", description = "Ich kann Euch bei der Anfertigung vieler Ausrüstungsgegenstände für Eure Seelenbande helfen.\n\nSie dürfen zwar jeweils nur einen Gegenstand anlegen, doch jeder verleiht ihnen eine neue Fähigkeit, die sie ohne ihn vielleicht nicht hätten.\n\nDieses Mal müsst Ihr Eure eigenen Materialien aus den Schattenlanden beschaffen. Wenn Ihr sie gesammelt habt, kehrt zu mir zurück und wir können die Fußpolster herstellen!", sourceObjective = "Baut mit Dactylis die Fußpolster des Herolds. Überprüft die Materialien im Handwerksfenster, um herauszufinden, wo Ihr sie sammeln könnt.", progress = "Material gefunden? Bauplan kann helfen!", completion = "Stiefel? Sehr schön! Bewahre ich auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61475] = { id = 61475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Waldes", description = "Ich wusste doch, wir verstehen uns! Willkommen in unserem Pakt. Nun ja, fast.\n\nEs fehlen nur noch ein paar Details. Kleinigkeiten. Ihr wisst schon: Schwüre zu leisten, Blutpakte zu schließen, Erstgeborene zu versprechen.\n\n<Mondbeere schnaubt ein Lachen.>\n\nWar nur ein Scherz!\n\nNa ja, bis auf die Schwüre. Die nehmen wir hier sehr ernst.\n\nWir treffen uns beim Lager vor dem Herz des Waldes!", sourceObjective = "Trefft Lady Mondbeere neben dem Flüchtlingslager vor dem Herz des Waldes im Ardenwald.", completion = "Das wird so lustig!", sourceObjectiveStatus = "unverified-source-field" }
quests[61477] = { id = 61477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Champions rufen" }
quests[61478] = { id = 61478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bescheidener Anfang", description = "Nachdem der Demutswächter jetzt wieder in altem Glanz erstrahlt, könnt Ihr Athanos vielleicht doch zurück in die Arena locken.\n\nGeht zum Prüfstein des Aspiranten, wo Eure Reise vor so langer Zeit begonnen hat. Sucht Schmiedin Sophone auf. Sie leitet alle an, die auf eine Begegnung mit Athanos aus sind.\n\nZeigt ihr den Speer. Sie wird wissen, was Ihr wollt, und Euch alles Weitere erklären.", sourceObjective = "Bringt den Demutswächter zu Schmiedin Sophone im Prüfstein des Aspiranten.", progress = "Was habt Ihr denn da?", completion = "Ich hätte nie gedacht, dass ich diesen Speer noch einmal sehe! Das wird wirklich interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[61479] = { id = 61479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Gestalten", description = "<Mondbeere sieht ernst aus.>\n\nAuch wenn Ihr sterblich seid, habt Ihr Euch doch entschlossen, einer unserer Champions zu werden. Solange Ihr treu für unsere Sache streitet, sind wir verpflichtet, Euch in unserer heiligen Halle gastlich zu empfangen und Euch unsere Gunst zu gewähren.\n\nAls ein Mitglied im Hof der Nacht kann ich auserwählten Sterblichen gewisse Kräfte verleihen.\n\n{name}, {class} von Azeroth, ich heiße Euch im ersten Baum willkommen, in Tirna Achiad, dem Herz des Waldes.\n\nFolgt mir bitte.", sourceObjective = "Begleitetet Lady Mondbeere in das Herz des Waldes und nehmt an der Zeremonie teil.", progress = "Nehmt diese Gunst und nutzt sie zum Wohle des Ardenwalds.", completion = "Möge dieser Segen Euch bei den bevorstehenden Prüfungen helfen, {name}.\n\nBevor unsere Königin Euch unsere Macht gewährt und wir Euch formell in unsere Reihen aufnehmen, gilt es, einige... Traditionen zu wahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[61485] = { id = 61485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sage das nur einmal", description = "Endlich sind wir voll und ganz bereit, den Plan der Baronin in die Tat umzusetzen.\n\nNun, da Ihr eingetroffen seid, werde ich unsere Rollen ein letztes Mal wiederholen. Dann werden wir unser Schicksal in die Hände nehmen.\n\nHört gut zu.", sourceObjective = "Sprecht mit Flüsterin Vyn über den Plan.", completion = "Setzen wir unseren Plan um.", sourceObjectiveStatus = "unverified-source-field" }
quests[61486] = { id = 61486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Banshee-Champion", description = "Ich... wir... Ich meine... er...\n\n<Der junge Kurier schluckt.>\n\nWir haben ihn gefunden. Wir haben den Pestrufer gefunden.\n\nIch war auf Patrouille wie schon Hunderte Male zuvor. Aber dieses Mal saß er auf der Veranda dieses alten Hauses mit diesen furchterregenden Hunden. Und ich schwöre, dass er mich schief angrinste und mich mit diesen schrecklichen roten Augen anstarrte und...\n\n<Der junge Kurier wischt sich den Schweiß von der Stirn.>\n\nEr ist in Marris' Siedlung. Unsere Truppen haben ihn umzingelt, aber, äh...\n\nIhr solltet vielleicht Eure Freunde zusammenrufen. Ich glaube nicht, dass er vorhat, sich zu ergeben.", sourceObjective = "Stellt Nathanos Pestrufer bei Marris' Siedlung in den Östlichen Pestländern.", completion = "Endlich hat einer der meist gefürchteten Feinde der Allianz sein Ende gefunden.\n\nGut gemacht, {name}. Wirklich sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[61488] = { id = 61488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Banshee-Champion", description = "<Der Bote ist sichtbar erschüttert.>\n\nWir haben davon gehört, dass... also, ich bin nicht sicher, wie ich das ausdrücken soll...\n\nDer Pestrufer wurde gefunden.\n\nDie Truppen der Horde haben Azeroth nach Zeichen von ihm abgesucht. Sie wollten ihn unbedingt für seine Taten büßen lassen.\n\nEine unserer Argentumpatrouillen hat ihn gefunden. Er hatte sich nicht in einem fernen Land versteckt. Er... war einfach auf seinem Anwesen.\n\nWir haben ihn umzingelt, aber, öh, ich glaube, wir sind dem nicht gewachsen.\n\nVielleicht könnt Ihr Eure Freunde zusammenrufen und ihn seiner gerechten Strafe zuführen.", sourceObjective = "Stellt Nathanos Pestrufer bei Marris' Siedlung in den Östlichen Pestländern.", completion = "<Der Lordregent zeigt ein gehässiges Lächeln.>\n\nEin treffliches Ende für den Pestrufer. Ich hätte ich es gern mit eigenen Augen gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61489] = { id = 61489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte und Ketzerei", description = "Echthra hat sich in einem der wenigen verbleibenden Gebäude im ehemaligen Haus der Augen in Maldraxxus eingerichtet.\n\nBringt ihr das Salbungsöl. Dann sollte sie Euch gestatten, ihre Erinnerung einzufangen. Aber seid vorsichtig. Sie ist überall als Meisterschützin bekannt und noch mehr für ihren flinken Finger am Abzug.\n\nViel Glück, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Findet Echthra im Haus der Augen in Maldraxxus.", progress = "Seid vorsichtig. Viele im Haus der Augen würden Eure Anwesenheit nicht tolerieren.", completion = "Lasst uns schnell reden. Bevor ich es mir anders überlege.", sourceObjectiveStatus = "unverified-source-field" }
quests[61490] = { id = 61490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg der Informationen", description = "Ah, das Salbungsöl. Ich hatte einen der Rekruten von Adrestes erwartet.\n\nWie dem auch sei. Ihr wollt meine Erinnerung für Eure Prüfung, ja? Ich fürchte, da ist einfaches Öl nicht genug.\n\nDa unser Haus gefallen ist, müssen wir uns selbst verteidigen. Dieser Turm gewährt zwar einigen Schutz, drängt uns jedoch auch in eine Ecke, wenn uns jemand auslöschen will.\n\nInformationen sind der Schlüssel zum Überleben. Benutzt meinen gesalbten Talisman, um mir Augen in allen Reichen zu schenken... sogar in der Bastion. Haltet Euch genau an die Liste. Und keine Fragen.\n\nDann sprechen wir über die Gegenleistung.", sourceObjective = "Platziert die Augen des Hasses im Haus der Rituale in Maldraxxus, im Äonischen Archiv in der Bastion, in Tirna Vaal im Ardenwald und auf Schloss Nathria in Revendreth.", completion = "Meine Augen sehen bereits mehr als je zuvor. Unser Pakt ist besiegelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[61492] = { id = 61492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prinzenwache", description = "Renathal hält sich gut, verbirgt aber großen Schmerz. Seine Wunden von Denathrius sind nicht verheilt.\n\nEr ist verletzlich.\n\nEr will Euch losschicken, um seine alte Festung Finsterwallturm mit Bannern zu sichern und verlässt sich auf seine eigene Stärke, um Feinde abzuschrecken. Eine taktisch schlechte Entscheidung.\n\nNehmt diesen kleinen Rest Anima und belebt Chelra den Klingenwall wieder. Zuletzt wurde sie am Finsterwall gesichtet. Belebt sie wieder, und sie kann Euch dabei helfen, den Turm einzunehmen.", sourceObjective = "Belebt Chelra den Klingenwall wieder und vertreibt den Feind aus dem Finsterwallturm.", progress = "Monatelang habe ich reglos gelitten. Ich hatte Sorge, ich würde nie wieder aufwachen.", completion = "Gut gekämpft. Das hält sie nicht lange auf, aber es wird Renathal dringend benötigte Zeit verschaffen.\n\nHabt Dank für die Infusion, Sterblicher. Ich werde die kostbare Anima gut nutzen, so lange sie hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[61509] = { id = 61509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitzerzeug der Bastion", description = "Chordy ist langweilig, soooo laaaangweilig!\n\nWollt Ihr Glücksbringer suchen? Auf Abenteuer mit Chordy gehen?\n\nWir gehen in das Land der Flügelleute und suchen dort wertvolle Glücksbringer.\n\nBereit?", sourceObjective = "Findet und sammelt mit Chordy 10 Stücke wertvolles Bergungsgut um die Bastion herum.", progress = "Haben wir etwas Gutes gefunden?", completion = "Interessant, die hier sind in besserem Zustand als die meisten Funde von Chordy.\n\nDie sind genau richtig. Vielen Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61510] = { id = 61510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üppige Beute", description = "Chordy will Abenteuer erleben! Ihr doch auch, oder?\n\nIch sammle Waffen, Rüstung und wertvolle Glücksbringer! Aber Glücksbringer findet man kaum dieser Tage.\n\nWir gehen in das Land der Baumleute! Zusammen finden wir dort viele, viele Glücksbringer!", sourceObjective = "Findet und sammelt mit Chordy 10 Stücke wertvolles Bergungsgut im Ardenwald.", progress = "Haben wir etwas Gutes gefunden?", completion = "Wo habt Ihr die denn gefunden? Die sind ja mit Dreck überzogen!\n\nPuh, was für ein Gestank! Hier, nehmt das und säubert Euch erstmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[61511] = { id = 61511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgelassene Dinge", description = "Chordy ist langweilig. Chordy will Abenteuer erleben! Ihr doch auch, oder?\n\nDie Leute in den großen Häusern haben viel Blingbling und Glücksbringer. Wir gehen da hin und holen uns was!\n\nSeid Ihr bereit?", sourceObjective = "Findet und sammelt mit Chordy 10 Stücke wertvolles Bergungsgut im Revendreth.", progress = "Haben wir etwas Gutes gefunden?", completion = "Das sind nützliche und interessante Funde.\n\nHabt Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61517] = { id = 61517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zz" }
quests[61518] = { id = 61518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte folgen", sourceObjective = "Folgt Navigatorin Xennir zum Treffpunkt.", progress = "Haltet die Augen offen.", completion = "Anscheinend hat man uns entdeckt. In Zeiten wie diesen benötigt man Flexibilität.", sourceObjectiveStatus = "unverified-source-field" }
quests[61520] = { id = 61520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Mnemis" }
quests[61522] = { id = 61522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenrückkehr", description = "Hier steht einiges an Arbeit an. Mmmmhmmm.\n\nHab einen riesigen Knochenkadaver in der Nähe gesehen. Ich will ein paar Teile davon nutzen.\n\nDachte, Ihr könnt mitkommen und mir helfen, das Ding zu Rathan zu bringen. Das wird ihm gefallen. Mmmmhmmm.\n\nIch könnte Euch glatt den ganzen Weg und wieder zurück tragen. Ihr seht gar nicht so groß aus.\n\nBereit für den Aufbruch?", sourceObjective = "Bringt den Knochenkadaver zu Rathan am Metzgerblock.", completion = "<Rathan schenkt Fliegenfalle einen beunruhigten Blick.>\n\nDas... Das ist... großartig!\n\nIch danke Euch beiden für diese Ressource!\n\n<Rathan lächelt Euch nervös an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61523] = { id = 61523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenrückkehr", description = "Hier steht einiges an Arbeit an. Mmmmhmmm.\n\nHab einen riesigen Knochenkadaver in der Nähe gesehen. Ich will ein paar Teile davon nutzen.\n\nDachte, Ihr könnt mitkommen und mir helfen, das Ding zu Rathan zu bringen. Das wird ihm gefallen. Mmmmhmmm.\n\nIch könnte Euch glatt den ganzen Weg und wieder zurück tragen. Ihr seht gar nicht so groß aus.\n\nBereit für den Aufbruch?", sourceObjective = "Bringt den Knochenkadaver zu Rathan am Metzgerblock.", completion = "<Rathan schenkt Fliegenfalle einen beunruhigten Blick.>\n\nDas... Das ist... großartig!\n\nIch danke Euch beiden für diese Ressource!\n\n<Rathan lächelt Euch nervös an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61524] = { id = 61524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gluthof", description = "Prinz Renathal ist bereit, den heutigen Gluthof zu eröffnen, wenn Ihr es seid.\n\nSprecht unbedingt mit dem restlichen Personal, um die Gästeliste und Annehmlichkeiten fertigzustellen, bevor wir den Hof eröffnen.\n\nVergesst nicht, dass wir die Gäste beeindrucken und davon überzeugen wollen, dass wir wissen, was wir tun. Wählt also Ausstattung, die die Gäste zufriedenstellt!\n\nSprecht mit Lady Ilinca, wenn Ihr Fragen zu den Gästen habt.\n\nSobald alles bereit ist, sagt es mir, und ich eröffne den Hof!", sourceObjective = "Stellt Eure Gäste- und Ausstattungsauswahl für den Gluthof fertig, und gebt dann Euer Bestes, um die Gäste zu beeindrucken.", sourceObjectiveStatus = "unverified-source-field" }
quests[61525] = { id = 61525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gluthof", description = "Prinz Renathal ist bereit, den heutigen Gluthof zu eröffnen, wenn Ihr es seid.\n\nSprecht unbedingt mit dem restlichen Personal, um die Gästeliste und Annehmlichkeiten fertigzustellen, bevor wir den Hof eröffnen.\n\nVergesst nicht, dass wir die Gäste beeindrucken und davon überzeugen wollen, dass wir wissen, was wir tun. Wählt also Ausstattung, die die Gäste zufriedenstellt!\n\nSprecht mit Lady Ilinca, wenn Ihr Fragen zu den Gästen habt.\n\nSobald alles bereit ist, sagt es mir, und ich eröffne den Hof!", sourceObjective = "Stellt Eure Gäste- und Ausstattungsauswahl für den Gluthof fertig, und gebt dann Euer Bestes, um die Gäste zu beeindrucken.", completion = "DAS war mal ein unvergesslicher Gluthof!\n\nWie wollt Ihr den nächste Woche überbieten?", sourceObjectiveStatus = "unverified-source-field" }
quests[61526] = { id = 61526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gluthof", description = "Prinz Renathal ist bereit, den heutigen Gluthof zu eröffnen, wenn Ihr es seid.\n\nSprecht unbedingt mit dem restlichen Personal, um die Gästeliste und Annehmlichkeiten fertigzustellen, bevor wir den Hof eröffnen.\n\nVergesst nicht, dass wir die Gäste beeindrucken und davon überzeugen wollen, dass wir wissen, was wir tun. Wählt also Ausstattung, die die Gäste zufriedenstellt!\n\nSprecht mit Lady Ilinca, wenn Ihr Fragen zu den Gästen habt.\n\nSobald alles bereit ist, sagt es mir, und ich eröffne den Hof!", sourceObjective = "Stellt Eure Gäste- und Ausstattungsauswahl für den Gluthof fertig, und gebt dann Euer Bestes, um die Gäste zu beeindrucken.", completion = "DAS war mal ein unvergesslicher Gluthof!\n\nWie wollt Ihr den nächste Woche überbieten?", sourceObjectiveStatus = "unverified-source-field" }
