quests[61540] = { id = 61540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beflügelt" }
quests[61541] = { id = 61541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede der Bande", description = "{name}, seid Ihr bereit für eine weitere Gabe?\n\nDie nächste Gunst, die wir Euch gewähren, ist eine Gunst der Bande. So wie Ihr Euch an uns gebunden habt, binden wir uns an Euch. Durch die Verbindung der Seelen werden wir größer als die Summe unserer Herzen.\n\n<Mondbeere beugt sich näher zu Euch.>\n\nKlingt echt beängstigend, oder? Keine Sorge! Ihr und Euer Seelenband werdet euch gegenseitig stärken.\n\nAuf meinen Aufruf nach Freiwilligen haben sich eine Menge Fae gemeldet. Ich habe jemanden ausgewählt, der Euch mit Sicherheit gefällt. Und es wird auch für sie ein Segen sein.\n\nGeht zu Flatterling. Sie wird Euch beiden helfen.", sourceObjective = "Trefft Euch mit Flatterling in der Schmiede der Bande.", completion = "Oh, wow! Ich helfe anderen immer furchtbar gern bei ihrer Seelenbindung! Das ist meine Lieblingsaufgabe!", sourceObjectiveStatus = "unverified-source-field" }
quests[61542] = { id = 61542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Bindung", description = "<Flatterling verschränkt die Hände und strahlt plötzlich geradezu vor Ruhe.>\n\nDie Seelenbindung ist nicht unwiderruflich. Aber dennoch sollte man gut über ein solches Band nachdenken, bevor man es eingeht.\n\nIhr und Euer Seelenband werdet das Herz und die Gedanken des anderen kennen. Eure Hoffnungen und Ängste, Eure Träume und Erinnerungen; das alles werdet Ihr miteinander teilen.\n\nSolange das Band besteht, seid Ihr eins. Immer vereint, auch wenn das Schicksal Euch trennt.\n\nIst das Band erst geknüpft, wächst Eure Verbindung über die körperliche Ebene hinaus und wird Euch beide ermächtigen.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", completion = "Ihr... habt ein wirklich interessantes Leben hinter Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61543] = { id = 61543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde: Flackernde Wachtfackel" }
quests[61544] = { id = 61544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde: Üppige Witwenblüte" }
quests[61545] = { id = 61545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde: Vollgestopfte Markwurzel" }
quests[61548] = { id = 61548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will raus", description = "Ansid wurde von den Wächtern der Gießerei gefangen genommen.\n\nSie scheinen uns erwartet zu haben, so viel also zum Element der Überraschung. Meine Baronin würde über meinen mangelnde Weitblick enttäuscht sein.\n\nOhne Ansid wird dieser Plan scheitern. Einer der Soldaten hat ganz sicher den Schlüssel zu seinem Käfig.\n\nWenn Ihr ihn findet, können wir den Plan der Baronin vielleicht doch umsetzen.", sourceObjective = "Findet den Osseinschlüssel und einen der Osseinstarkarme und befreit damit Ansid.", progress = "Seid auf der Hut.", completion = "Exzellente Navigation. Vielleicht solltet Ihr die Nekropole steuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[61549] = { id = 61549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dürrezustand" }
quests[61550] = { id = 61550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärken des Bands", description = "Ich weiß, wie Ihr Euch fühlt... und was Ihr um Eurer Welt willen ertragen habt.\n\nIhr wisst jetzt auch von meinen eigenen Triumphen und Tragödien.\n\nUnser Band wird mit der Zeit stärker werden. Aber jetzt wollen wir erst einmal sehen, was es uns beschert hat.\n\nDer Ardenwald bedarf unserer Hilfe. Wir müssen alles in unserer Macht Stehende tun, um ihn zu retten.", sourceObjective = "Aktiviert einen Seelenbandbonus, indem Ihr die Schmiede der Bande benutzt.", progress = "Vereint sind wir stärker.", completion = "Zusammen ist für uns nichts unmöglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61551] = { id = 61551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermalmt sie alle", description = "Die Anlegerplattform ist der beste Ausgangspukt für den Zutritt zur Nekropole da oben. Aber ein weiterer Kampf liegt noch vor uns.\n\nVollstreckerin Borgulla überwacht sämtliche Arbeiten dort. Wir müssen sie ausschalten, wenn wir ungehindert vorankommen wollen.\n\nSie ist eine mächtige Gegnerin, aber offenbar hat Ansid etwas Sprengstoff bei sich... Den können wir zu unserem Vorteil nutzen.", sourceObjective = "Verwendet Ansids Sprengstoff, um Vollstreckerin Borgulla zu töten.", completion = "Eure Stärke beeindruckt mich immer wieder aufs Neue.", sourceObjectiveStatus = "unverified-source-field" }
quests[61552] = { id = 61552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd sieht alles", description = "Die Wilde Jagd beschützt. Viele Augen halten Ausschau nach Gefahr. Viele Ohren lauschen nach Geheimnissen.\n\nBehüterin Vesperblüte lenkt die Augen und Ohren des Waldes.\n\nSucht unser neues Wachstum auf und bittet sie um Rat.", sourceObjective = "Aktiviert Abenteuer und sucht dann Behüterin Vesperblüte auf.", completion = "Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[61553] = { id = 61553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Macht", description = "Es ist die Pflicht der Wilden Jagd, alle zu erlegen, die unseren Schutzbefohlenen schaden wollen, und auch, unsere Grenzen zu sichern. Aber je mehr sich diese Krise ausweitet, desto vielfältiger werden auch unsere Pflichten gegenüber Königin und Hain.\n\nUnd genau hier beginnt meine Aufgabe. Ich muss über alles Bescheid wissen, was in diesem schier endlosen Wald vorgeht. Mir obliegt es, unsere Ressourcen so einzusetzen, dass sie unserer Königin helfen.\n\nGestattet mir eine kleine Demonstration...", sourceObjective = "Verwendet den Befehlstisch, um Eure Streitkräfte auf ein Abenteuer zu entsenden.", completion = "Ich habe keinerlei Zweifel, dass sie ihre Mission erfolgreich ausführen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61554] = { id = 61554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gespielt ist halb gewonnen", description = "Ihr fragt Euch vielleicht, welche letzte Gunst wir Euch gewähren, oh Champion des Ardenwalds, <Bittsteller/Bittstellerin> unserer Jagd.\n\n<Vesperblüte scheint zu grinsen... aber das ist vielleicht nur eine optische Täuschung.>\n\nBevor unsere Königin Euch unsere Macht gewährt und wir Euch formell in unsere Reihen aufnehmen, gilt es, einige... Traditionen zu wahren.\n\nLady Mondbeere erwartet Euch im Sanktum und wird Euch alles Weitere erläutern.\n\nHals- und Beinbruch.", sourceObjective = "Sucht Lady Mondbeere in der zentralen Halle im Herz des Waldes auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61555] = { id = 61555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochinquisitor Vetar" }
quests[61556] = { id = 61556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Gäste" }
quests[61557] = { id = 61557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Echo im Dunkeln", sourceObjective = "Trefft Bolvar Fordragon in Oribos.", completion = "<Bolvar verzieht das Gesicht unter Schmerzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61558] = { id = 61558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vision des Hochlords", description = "<Thrall runzelt die Stirn.>\n\nWir sprachen gerade mit dem Hochlord, als ihn ein Schmerz durchfuhr.\n\nEr sagte, er könne etwas sehen, das sich im Schlund regt, im Turm des Kerkermeisters.\n\nDer Schmerz scheint immer noch zuzunehmen. Wir müssen herausfinden, was er spürt.", sourceObjective = "Findet heraus, was Bolvar im Inneren von Torghast spürt.", progress = "Wir müssen die Wahrheit erfahren.", completion = "Das sind wahrlich finstere Aussichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61559] = { id = 61559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geburt einer Gramklinge", description = "Als sein Vater verschwunden war, habe ich mich um Anduin wie um einen Sohn gekümmert. Ihn so zu sehen, der Gnade Sylvanas' ausgeliefert...\n\n<Bolvars Augen scheinen zu glühen.>\n\nWir müssen etwas unternehmen.\n\nLasst Euch Zeit und sagt mir, wenn Ihr bereit seid, über die nächsten Schritte zu sprechen.", sourceObjective = "Sprecht mit Bolvar und den anderen über die Vision.", completion = "Wir müssen Bolvar retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[61564] = { id = 61564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunst: Polierter kyrianischer Schild" }
quests[61565] = { id = 61565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[61567] = { id = 61567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Absichten", description = "Meine Spione haben mehrere Astralprojektoren entdeckt, die Markgraf Gharmal nutzt, um die Truppen im Flickenhof zusammenzurufen.\n\nIch will nicht, dass ein Schwarm rasender Konstrukte in der letzten Schlacht auf uns niederprasselt. Ihr seht sicherlich den Vorteil darin, ihren Eifer zu dämpfen.\n\nKümmert Euch darum, dass diese Projektoren zerstört werden. Wir glauben, dass sie im Hof sind.", sourceObjective = "Zerstört die südwestlichen, nordwestlichen und nordöstlichen Astralprojektoren.", completion = "Gharmals Einfluss ist hier tief verwurzelt, aber er wird dank Eurer Anstrengungen schneller verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61569] = { id = 61569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zum Ruin", description = "Endlich haben wir unser Ziel erreicht.\n\nDie Nekropole ruht über uns, mit dieser Plattform verbunden durch einen nekrotischen Haltebolzen.\n\nTwigin kann Euch zur Spitze der Nekropole fliegen. Sobald Ihr diesen Schlüsselstein einsetzt, können wir sie befehligen.\n\nWir werden uns auf die Abreise vorbereiten. Kommt zu uns, wenn Ihr fertig seid.\n\nBald ist der Sieg unser.", sourceObjective = "Fliegt mit Twigin zur Spitze der Nekropole und setzt den Runenschlüsselstein ein.", progress = "Unsere Mission ist fast vollendet.", completion = "Kommt, {name}. Wollt Ihr Euren Erfolg nicht mit eigenen Augen sehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[61586] = { id = 61586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegerische Machenschaften", description = "Die Allianz mit der Bastion verleiht uns die Stärke, Gharmal und das Haus der Konstrukte zu zerschmettern.\n\nWir sammeln die für diesen Angriff benötigten Vorräte zusammen, doch unsere Soldaten brauchen einen großen Champion, der sie in die Schlacht führt.\n\nBeweist Ihnen, dass Ihr der Champion seid, nach dem sie suchen.", sourceObjective = "Erhöht Euren Ruhm.", completion = "Gut gemacht, Schlundgänger. Unsere Streitkräfte sind angriffsbereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61593] = { id = 61593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungskrise" }
quests[61594] = { id = 61594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da geht's raus", description = "Wir sind bereit, die Nekropole zu starten. Wir müssen uns beeilen, bevor Markgraf Gharmal versucht, sich einzumischen.\n\nSprecht mit Vyn, wenn Ihr bereit seid, aber wir müssen uns beeilen.\n\nUnsere Schatten werden auf ganz Maldraxxus fallen.", sourceObjective = "Gebt Flüsterin Vyn den Befehl zum Start der Nekropole.", completion = "Es ist Zeit aufzubrechen.", sourceObjectiveStatus = "unverified-source-field" }
