quests[61615] = { id = 61615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneiderei: Heimsuchende Kapuze" }
quests[61616] = { id = 61616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gluthof", description = "Wir haben alles, was wir brauchen, um unseren ersten echten Gluthof zu veranstalten, wenn Ihr bereit seid.\n\nNehmt Euch einen Augenblick, um alles fertigzustellen, dann eröffnen wir den Hof!\n\nVergesst nicht, dass wir Grufthüter Kassir beeindrucken und ihn davon überzeugen wollen, dass wir wissen, was wir tun. Wählt also unbedingt die Erfrischungen und die Unterhaltung, die wir für ihn organisiert haben!\n\nSobald alles bereit ist, lasst es mich wissen, und ich eröffne den Hof!", sourceObjective = "Stellt Eure Gäste- und Ausstattungsauswahl für den Gluthof fertig und gebt dann Euer Bestes, um Euren Gast zu beeindrucken.", completion = "Unglaublich! Makellos! Der perfekte Festherold!\n\nUnd Ihr habt Euch auch gut geschlagen.\n\nLasst uns das nächste Woche wiederholen!", sourceObjectiveStatus = "unverified-source-field" }
