quests[61635] = { id = 61635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstörte Seelen", description = "Unsere Arbeit hier spricht sich herum, es sind neue Seelen eingetroffen, die sich uns anschließen wollen!\n\nNehmt ihre Anfragen für neue Konstruktkörper entgegen. Vielleicht können wir auch für sie neue Konstrukte bauen!", sourceObjective = "Nehmt die Anfragen von den anwesenden Seelen entgegen.", completion = "So viele Seelen, es gibt so viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[61637] = { id = 61637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einigkeit", description = "Ein einzigartiges Konstrukt hat sich entschlossen, sich uns anzuschließen, aber durch seine unethische Entstehung ist es sehr verstört.\n\nDie Verschmelzung fragmentierter Kyrianerseelen in diesem Konstrukt sorgt für Schmerz und Leid. Wir müssen einen Weg finden, diese Seelen zu harmonisieren, damit sie in Frieden miteinander leben können.\n\nStellt die Bindungen des Wohlbefindens her und befreit das seelenverschmolzene Konstrukt von seinem Leid.", sourceObjective = "Befreit das seelenverschmolzene Konstrukt von seinem Leid.", progress = "Konntet Ihr diesem Konstrukt helfen?", completion = "So viele Seelen, die jetzt in Harmonie leben. Vielleicht wird dieses Konstrukt jetzt hier sein Glück und ein neues Zuhause finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61638] = { id = 61638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiserne Lösung", description = "Unsere Arbeit hier spricht sich herum, es sind neue Seelen eingetroffen, die sich uns anschließen wollen!\n\nNehmt ihre Anfragen für neue Konstruktkörper entgegen. Vielleicht können wir auch für sie neue Konstrukte bauen!", sourceObjective = "Nehmt die Anfragen von den anwesenden Seelen entgegen.", completion = "So viele Seelen, es gibt so viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[61667] = { id = 61667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimlich geschmiedet" }
quests[61689] = { id = 61689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungskrise" }
quests[61697] = { id = 61697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Zeitalter", description = "Mit dieser letzten Ermächtigung wird das Emblem des Aufstiegs nicht nur durch die Bastion, sondern alle Pakte bestärkt.\n\nSchon bald werden sich neue Aufgestiegene in diesen Hallen einfinden, während die Aspiranten auf ihre ersehnten Prüfungen warten.\n\nNichts davon wäre ohne Eure Hilfe möglich gewesen, <Schlundgänger/Schlundgängerin>. Die Ehre der Aktivierung des Emblems gebührt Euch.", sourceObjective = "Aktiviert das Emblem des Aufstiegs.", progress = "Dies ist ein glorreicher Moment für alle Kyrianer.", completion = "Jetzt, wo das Emblem vollständig ist, müssen wir unseren Blick wieder auf die Verschmähten richten.\n\n<Ihr bemerkt, dass Larvi Euch erwartungsvoll anschaut.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61699] = { id = 61699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Schleim um Nichts" }
quests[61701] = { id = 61701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchung des Hains", description = "Ganz offensichtlich hat hier ein Kampf stattgefunden. Ich fürchte, dass die Drust Kivarr mitgenommen haben.\n\nVor Eurer Ankunft habe ich die Umgebung ausgespäht. Der Abendhain wurde überrannt.\n\nDie Drust können nicht weit sein. Vielleicht können wir sie noch finden. Ich bete nur, dass wir nicht zu spät kommen...", sourceObjective = "Sucht nach Kivarr im Abendhain im Ardenwald.", completion = "Ulfar hat Euch geschickt, um nach mir zu suchen? Befreit mich aus diesem Käfig, dann werde ich Euch helfen, so gut ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[61702] = { id = 61702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneller Eingriff", description = "Die Drust haben gerade Kivarr fortgebracht. Sie wollen sie in einem ihrer Rituale opfern!\n\nWenn wir uns beeilen, könnt Ihr sie vielleicht noch retten! Ich weiß, wo sich der Opferaltar der Drust befindet... dort ist es schrecklich, aber ich kann Euch da hinbringen!\n\nWir dürfen keine Zeit verschwenden. Folgt mir!", sourceObjective = "Rettet Kivarr aus dem Abendhain im Ardenwald.", completion = "Nicht einen Moment zu früh! Ich weiß Eure Pünktlichkeit zu schätzen.\n\nMeine Höhle ist nicht weit von hier. Wir sollten uns beeilen, bevor noch mehr Drust kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61703] = { id = 61703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtwurz", description = "Um das Ritual durchführen zu können, benötige ich Nachtwurz aus dem Dunkelvorstoß.\n\nDas ist eine besondere Pflanze, die nur auf Böden wächst, die von Drustmagie verdorben wurden.\n\nDer Dunkelvorstoß befindet sich unweit meiner Höhle im Westen. Dieser einst friedvolle, üppige Hain ist jetzt eine verseuchte Ödnis.\n\nIch werde in das Herz des Waldes reisen, um das Ritual vorzubereiten. Trefft mich dort, wenn Ihr Nachtwurz besorgen konntet.", sourceObjective = "Sammelt 12 Nachtwurzen im Dunkelvorstoß im Ardenwald.", progress = "Habt Ihr die Reagenzien dabei?", completion = "Gut. Ihr konntet genug Nachtwurz für das Ritual finden. Leider gibt es da noch ein weiteres Problem...", sourceObjectiveStatus = "unverified-source-field" }
quests[61704] = { id = 61704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Gästezusagen", description = "Prinz Renathal wird bestimmte Gäste zu jedem Gluthof einladen wollen.\n\nIn Zukunft werden wir die Gästeliste anpassen und es vereinfachen können, es jedem Gast recht zu machen. Aber beim ersten Mal sollten wir uns nach dem Prinzen richten.\n\nArbeitet mit Lord Garridan und Lady Ilinca zusammen, um sicherzustellen, dass der Grufthüter die Einladung annimmt.\n\nWenn Ihr Grufthüter Kassir auf Euren Abenteuern noch nicht begegnet sein, müsst Ihr Euch vielleicht vorstellen, bevor er Euch zuhört.", sourceObjective = "Sprecht mit Lord Garridan, um Eure Gästeliste zu sehen, und trefft dann Grufthüter Kassir, um seine Zusage zu erhalten.", completion = "Es ist klug vom Prinzen, Hof zu halten. Eine zeitlose Tradition des Einflusses und Prestiges in diesem Reich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61705] = { id = 61705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Erfrischungen", description = "Wir sollten immer Erfrischungen am Gluthof reichen und die Auswahl der Erfrischungen auf die Gäste zuschneiden.\n\nGlücklicherweise kenne ich unseren ersten Gast gut. Wie Theotar mag er es förmlich.\n\nArbeitet mit Stefan dem Wählerischen zusammen, um alles zu besorgen, das wir für ein edles Teekränzchen brauchen.", sourceObjective = "Sprecht mit Stefan dem Wählerischen, um Eure Erfrischungsoptionen zu sehen, und schließt dann Tubbins' Quest für den Teekränzchenvertrag ab.", completion = "Wie schlau! Tubbins' Tee ist bester Tee!", sourceObjectiveStatus = "unverified-source-field" }
quests[61706] = { id = 61706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Unterhaltung", description = "Jeder liebt Unterhaltung!\n\nUnser erster Gast kommt aus den Hallen der Sühne, und er wird eine Darbietung der mächtigen Rituale, zu denen die Anklägerin fähig ist, zu schätzen wissen.\n\nArbeitet mit Kuhl zusammen, um alles zu besorgen, das wir für die Darbietung der Rituale der Buße am Gluthof benötigen.", sourceObjective = "Sprecht mit Kuhl, um Eure Unterhaltungsoptionen zu sehen, und schließt dann Gresits Quest für den Ritualvertrag ab.", completion = "Ein neuer Hof in Revendreth? Die Anklägerin muss erfreut sein, dass Ihr die Sühnerituale zu einem Teil der Festlichkeiten gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[61707] = { id = 61707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbröckelte Realität", description = "Da die Dürre und die Verschlinger unsere Bauten zerstören, verlieren die Strukturen ihren Halt in der Realität. Ist keine saubere Angelegenheit. Manche Trümmer stecken noch voller Anima.\n\nWenn Ihr da draußen seid, seid ein Steinrücken und bringt uns solche Trümmer.\n\nWir können sie zu neuen Strukturen verbauen, während Ihr Heldentypen die Anima wieder zum Fließen bringt.\n\nBringt sie her und wir kümmern uns drum.", sourceObjective = "Bergt 100 durchdrungenen Schutt.", progress = "Beeindruckend, wie viel Ihr mit Euren spillerigen Ärmchen tragen könnt.", completion = "Bei Euch hat man auf Stein gebaut. Klasse.", sourceObjectiveStatus = "unverified-source-field" }
quests[61708] = { id = 61708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftentzug" }
quests[61709] = { id = 61709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenbeutel", description = "Ich habe Ara'lon losgeschickt, um den Drust einen Hexenbeutel zu stehlen... Eine gefährliche Aufgabe, und er ist noch nicht wieder zurückgekehrt.\n\nDie Nachtkreischerinnen der Drust tragen viele der Reagenzien, die wir für das Ritual brauchen. Sie sind unabdingbar.\n\nIhr müsst Euch in das Eichengehölz begeben, um einen ihrer Hexenbeutel zu beschaffen... und Ara'lon zu finden, wenn Ihr könnt.", sourceObjective = "Sammelt 1 Hexenbeutel im Eichengehölz im Ardenwald.", progress = "Habt Ihr den Beutel? Und was ist mit Ara'lon?", completion = "Dies enthält alles, was wir brauchen. Nur einen kleinen Moment. Ich werde sofort die Reagenzien vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61710] = { id = 61710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zerbrochene Speer", description = "<Die zersplitterten Überreste eines Sylvarispeers sind überall verstreut. Euch wird klar, dass es sich um Ara'lons Speer handelt.>\n\nDies bestätigt, dass sich Ara'lon hier aufgehalten hat. Leider ist er selbst nicht zu sehen.\n\nIhr solltet Lord Herne über Eure Entdeckung informieren.>", sourceObjective = "Bringt die Reste von Ara'lons Speer zu Lord Herne im Herz des Waldes im Ardenwald.", progress = "Was bringt Ihr für Neuigkeiten?", completion = "Das ist kein gutes Zeichen, aber ich bin noch nicht gewillt, die Hoffnung aufzugeben, dass Ara'lon überlebt hat. Er könnte noch irgendwo da draußen sein.\n\nIch werde einen Suchtrupp aufstellen. Wir werden ihn finden und nach Hause bringen... welches Schicksal ihn auch befiel. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61711] = { id = 61711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual der Reinigung", description = "Ich habe die Vorbereitungen für das Ritual abgeschlossen. Der Moment der Wahrheit ist gekommen.\n\nDer Drustfetisch, den Ulfar Euch gab, wird die Kräfte des Rituals auf Gweyir kanalisieren und dem Fluch ihrer Besessenheit entgegenwirken.\n \nDas wird nicht angenehm, und vielleicht scheitert es. Aber das ist die einzige Möglichkeit, die wir haben, um sie zu befreien.", sourceObjective = "Schließt das Ritual der Reinigung ab.", progress = "Das Ritual ist unsere einzige Hoffnung, Gweyir zu befreien. Wir müssen es versuchen...", completion = "Ihr habt das Ritual in bewundernswerter Weise durchgeführt, doch Gorak Zhars Macht war zu stark für Gweyir. Ich fürchte, es gibt nichts mehr, was wir tun können.\n\nDie maskierten Fae scheinen für uns verloren zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[61713] = { id = 61713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett der Schnelligkeit", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das Euren Seelenbanden einen Vorteil auf dem Pfad des Aufstiegs schenken könnte.\n\nDactylis sollte Euch dabei helfen können, so eines herzustellen.>", sourceObjective = "Bringt den Bauplan: Amulett der Schnelligkeit zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61714] = { id = 61714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergoldeter Abakus", description = "<Ein schön gearbeiteter Abakus ruht in Euren Händen. Sein Rahmen schimmert und glänzt im Licht, seine Perlen sind glatte, goldene Kugeln.\n\nEuer Provost wird dies nicht nur als nützliches, sondern auch als exquisites Geschenk schätzen.>", sourceObjective = "Ruft Euren Provostbegleiter mit 'Provost beschwören' und übergebt den vergoldeten Abakus.\n\nBereitgestellter Gegenstand:", completion = "<Euer Begleiter blickt voller Ehrfurcht.>\n\nHab keine Worte... so schön! Kann jetzt viel mehr im Auge behalten. Aber was soll ich zählen...\n\nAha! Eure Sachen zählen. Keine Sorge, kann ausgezeichnet zählen. Juu-chuu!", sourceObjectiveStatus = "unverified-source-field" }
quests[61715] = { id = 61715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersuchen des Hochlords", description = "Die Informationen, die Ihr in Maldraxxus ans Tageslicht gebracht habt, sollten die Kriegstrommeln zwischen den Nekrolords und den Kyrianern zum Verstummen bringen.\n\nUnd diese Nachricht des Primus... außergewöhnlich!\n\nIch empfehle Euch, den Rat von Hochlord Fordragon einzuholen... er wirkt jedoch beschäftigt. Besucher aus Eurer Welt sind an ihn herangetreten. Auf ziemlich beharrliche Weise, muss ich sagen.\n\nDie Feinheiten der Interaktion unter Sterblichen entziehen sich mir. Doch ihr Dialog scheint sich... ausgesprochen intensiv gestaltet zu haben.\n\nVielleicht könnt Ihr dem Hochlord in dieser Angelegenheit beistehen.", sourceObjective = "Sprecht mit Bolvar Fordragon.", completion = "<Selbst in Bolvars zernarbtem, verzerrtem Antlitz werden seine Gefühle sichtbar.>\n\nMeine Tochter... hier. Ich hätte nie gedacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[61716] = { id = 61716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Dunkelheit", description = "Als ich mir die Krone des Lichkönigs auf das Haupt setzte, wollte ich, dass die Welt mich als tot erachtet. Sogar meine Tochter Taelia. Ich... dachte, eine Lüge wäre gnädiger als die Wahrheit.\n\nDoch sie ist nicht mehr das kleine Mädchen, das ich in Kul Tiras zurückließ. Ich weiß, dass meine Entscheidung selbstsüchtig war.\n\n<Bolvar zögert.>\n\nSie und Lady Menethil haben mich gebeten, in den Schlund zu blicken, um herauszufinden, ob unsere Verbündeten noch leben. Es ist eine gefährliche Bitte, doch eine, die ich nicht abschlagen kann.\n\nHelft mir, mich auf den zerbrochenen Helm zu konzentrieren. Gemeinsam erhaschen wir vielleicht eine Spur der Wahrheit.", sourceObjective = "Erlebt Bolvars Vision des Schlunds.", progress = "Es gibt viel zu tun.", completion = "Fürwahr, eine besorgniserregende Vision. Aber wir dürfen die Hoffnung nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[61717] = { id = 61717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormlingfänger: Ruhige Teiche" }
quests[61725] = { id = 61725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Andenken", progress = "Ich freue mich auf das baldige Eintreffen unseres gestohlenen Eigentums, Schlundgänger.\n\nIhre Klauerei trübt ein ansonsten herrliches Ereignis.", completion = "<Hüter Ta'saran beäugt jedes Andenken vorsichtig.>\n\nAlle in akzeptablem Zustand. Ihre Rückkehr wird schriftlich festgehalten.\n\nIhr müsst keinen Racheakt mehr für den Diebstahl befürchten." }
quests[61728] = { id = 61728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valis der Grausame" }
quests[61729] = { id = 61729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Rahel", sourceObjective = "Rahel ist aus Dunkelhafen eingetroffen, um uns dabei zu helfen, ich zitiere: \"alle umzubringen\". Sie scheint sehr entschlossen, den Kampf aufzunehmen.\n\nEs scheint sie sehr fröhlich zu stimmen, wieder mit Euch zu arbeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61730] = { id = 61730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene König", description = "Wir haben König Anduin in Torghast nicht ausfindig machen können. Ich fürchte, dass wir eine Ewigkeit lang vergeblich diese endlosen Korridore absuchen könnten.\n\nWir müssen erfahren, welches Schicksal ihm widerfahren ist. Ein Blick in diesen Turm ist mit großen Risiken verbunden, aber wir haben keine andere Wahl.\n\nIch brauche Eure Hilfe, {name}. Wir werden den zerbrochenen Helm der Herrschaft verwenden und einen Blick in diesen höllischen Ort werfen.\n\nVielleicht können wir zusammen dieser hungrigen Dunkelheit trotzen.", sourceObjective = "Benutzt den Helm der Herrschaft, um einen Blick nach Torghast zu riskieren.", completion = "Anduin mag unversehrt erscheinen, aber seine Seele ist in Gefahr.\n\nSylvanas Windläufer darf auf keinen Fall ihren Plan umsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61731] = { id = 61731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Kuriositäten", progress = "Interessant. Sehr interessante Schmuckstücke...\n\nKönnte ich zum Studieren behalten? Werde viel lernen.", completion = "Sehr interessant! Habt Dank!\n\n<Mikanikos beginnt sofort, eines der Schmuckstücke zu zerlegen, um es zu studieren.>" }
quests[61732] = { id = 61732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Angewohnheiten sterben nie", description = "Eure Umverteilung der Anima war bisher löblich.\n\nAber Venthyr bleiben Venthyr. Sie verbringen Äonen damit, Seelen über die Torheit von Gier und Horten aufzuklären, erkennen diese Schwächen aber oft nicht bei sich selbst.\n\nMeine Späher haben einige Venthyr dabei beobachtet, wie sie die Anima entziehen, die Ihr umverteilt habt. Sie horten sie dann in ihren Anwesen und Häusern. \n\nDurchsucht diese Orte und stellt die gehortete Anima sicher, damit wir sie sinnvoller einsetzen können.", sourceObjective = "Stellt 10 gehortete Animakäfige sicher.", completion = "Gier. Eine der wenigen Sünden, die nicht geläutert, sondern von Graf Denathrius in jüngeren Zeitaltern auch noch in den Venthyr gefördert wurde. \n\nWir haben beobachtet, wie er sein Volk damit beherrschte, um es stagnierend und gespalten zu halten. \n\nRenathals Methoden sind der einzige Ausweg.", sourceObjectiveStatus = "unverified-source-field" }
quests[61733] = { id = 61733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Sack voll Kriecher", description = "Gut. Wir wissen Eure Arbeit bisher zu schätzen, ganz sicher.\n\nAber jetzt hab ich 'ne Aufgabe für Euch, die uns Gräbern dabei helfen würde, Eure Anima gut zu nutzen.\n\nKriecher.\n\nNicht irgendwelche, sondern Morastkriecher. Sehen anders aus und schmecken anders und sind ein Fest, wenn man es richtig anstellt.\n\nWenn Ihr so durch Revendreth lauft, schnappt Euch alle Kriecher, die Ihr seht, und stopft sie in den Sack hier. Ich zahl auch.", sourceObjective = "Sammelt 20 Morastkriecher.", completion = "Sieh sich das einer an!\n\nEin großer voller Sack Kriecher mit ihren Blinzelaugen und ihrem Schimmelatem.\n\nPutzig, was? \n\nEin paar von denen griffbereit, und die Laune der Jungs bei der Arbeit steigt. Wissen wir wirklich alle zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61734] = { id = 61734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenzählung", description = "Die Kuratorin kannte einst den Inhalt und Standort jedes Sündensteins in Revendreth ab Gründung dieses Reichs.\n\nLeider hat ihre Zeit im Schlund diesen Teil ihres riesigen Intellekts gestört, und wir können uns in dieser Hinsicht nicht mehr auf ihr Wissen verlassen. Zumindest eine Zeitlang nicht mehr. Daher ist es meine Aufgabe, ein 'lebendes' Archiv aufzubauen.\n\nWenn Ihr nach Revendreth vorstoßt, bitte ich Euch, Inhalt und Standort bestimmter Sündensteine zu bestimmen. Das würde mit dem Archiv helfen.", sourceObjective = "Untersucht 7 verlorene Sündensteine.", completion = "Im Laufe der Zeit und mit genug Informationen können wir das Wissen der Kuratorin so verankern, dass sie wieder zu dem unschätzbaren Quell des Wissens wird, der sie einst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[61735] = { id = 61735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erwachen unserer Verbündeten", description = "Ich benötige Eure Dienste.\n\nIch habe eine Gruppe von Steingeborenen in Revendreth ausfindig gemacht, die unserer Sache nicht abgeneigt sind oder bereits Teil davon waren, bevor sie in ihren Steinschlummer zurückfielen.\n\nIhr habt uns die benötigte Anima beschafft, und jetzt gilt es, sie einzusetzen. Geht zu unseren Verbündeten und erweckt sie. Ich habe einen Animabehälter für einfacheren Transport in dieser Angelegenheit entwickelt. \n\nWir brauchen eine Armee, wenn wir einer Armee gegenüberstehen.", sourceObjective = "Erweckt 15 verbündete Steingeborene.", completion = "Furchterregend, nicht wahr? Herrliche Waffen, entstanden durch beste Handwerkskunst, die seit der Verschmelzung der Schattenlande perfektioniert wurde. \n\nSie werden in Zukunft von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61736] = { id = 61736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus unserer Mitte gestohlen", description = "Da gibt es vieles, das Ihr wissen solltet, {name}.\n\nDie Geißel ist zurück. Jetzt, wo der Helm der Herrschaft zerschmettert ist, fallen sie über uns her. Nichts kann sie aufhalten.\n\nUnd noch schlimmer ist, dass Sylvanas Windläufer ihre Agenten direkt in das Herz unserer Königreiche entsendet hat, um jene zu entführen, die ihre Kriegspläne durchkreuzt haben.\n\nSprecht mit Weißsträhne. Sie kann Euch den Rest erzählen.", sourceObjective = "Sprecht mit Sally Weißsträhne über die Entführungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61737] = { id = 61737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus unserer Mitte gestohlen", description = "Da gibt es vieles, das Ihr wissen solltet, {name}.\n\nDie Geißel ist zurück. Jetzt, wo der Helm der Herrschaft zerschmettert ist, fallen sie über uns her. Nichts kann sie aufhalten.\n\nUnd noch schlimmer ist, dass Sylvanas Windläufer ihre Agenten direkt in das Herz unserer Königreiche entsendet hat, um jene zu entführen, die ihre Kriegspläne durchkreuzt haben.\n\nSprecht mit Nazgrim. Er kann Euch den Rest erzählen.", sourceObjective = "Sprecht mit Nazgrim über die Entführungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61738] = { id = 61738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthof: Der Verschüttete Kelch", description = "Kuhl war schlau, Euch zu mir zu schicken. Die Band \"Der Verschüttete Kelch\" spielt die beste Musik diesseits des Schlunds!\n\nAllerdings sind sie noch nicht bereit, auf Tournee zu gehen.\n\nDie Musiker sind alle in Sicherheit in der Gruft hinter mir, aber ihre Instrumente wurden von der spießigen Nachbarschaftsbehörde konfisziert!\n\nLärmbeschwerden und so.\n\nHelft mir, sie zurückzubekommen, rekrutiert vielleicht unterwegs noch einige Groupies und Roadies, dann liefern wir Euch das beste Konzert, das Euer Hof je erlebt hat!", sourceObjective = "Rekrutiert 10 Groupies und 10 Roadies mit Bandplakaten und holt 3 konfiszierte Musikerausstattung zurück.", progress = "Jeder Venthyr oder Gräber reicht aus. Wir sind nicht wählerisch, was unsere Anhänger angeht.", completion = "Ich weiß nicht, welche Werbetricks Ihr benutzt habt, aber sie haben funktioniert.\n\nJede Menge Gräber und Venthyr sind vorbeigekommen, um sich uns anzuschließen!\n\nDer Verschüttete Kelch kann auf Tournee gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[61739] = { id = 61739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron auf Abwegen", description = "Es ist mir zu Ohren gekommen, dass Ihr eine Verschwörung von Baron Kel'Thuzad aufzudecken versucht.\n\nDieser Emporkömmling ist mir seit seiner Ankunft im Haus der Rituale ein Dorn im Auge. Er hat mir nicht nur meinen rechtmäßig verdienten Titel gestohlen, sondern mich auch aus den Geschäften des Hauses gedrängt.\n\nIch habe noch keine Beweise gefunden, die Sin'danes Verehrung für den neuen Baron trüben könnten, und deshalb biete ich Euch ein Abkommen an. Ich gewähre Euch Zugang zum Haus der Rituale, und im Gegenzug helft Ihr mir, Kel'Thuzad zu stürzen.\n\nSind wir uns einig?", sourceObjective = "Öffnet Balmedars Vorräte am Turm nahe des Skapliagrats.", completion = "<Balmedars Stimme schallt aus dem schwebenden Auge.>\n\nIhr habt doch nicht etwa gedacht, dass ich hier ein persönliches Treffen mit Euch riskieren würde, oder?\n\nKommt, es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[61740] = { id = 61740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Liebling mehr", description = "Wir werden eine Illusion erschaffen müssen, um Euch Zutritt zum Haus der Rituale zu verschaffen. Für die Aufnahme in Kel'Thuzads inneren Zirkel eignet sich aber nicht irgendeine Illusion. Dafür brauchen wir etwas... Bestimmtes.\n\nWir benötigen eine Leiche.\n\nGlücklicherweise führt eine der Lieblingsakolythinnen des Barons außerhalb des Hauses ein Ritual aus. Ihr müsst Euch den Weg zu ihr freikämpfen, aber ich habe keinen Zweifel daran, dass Ihr dazu fähig seid.", sourceObjective = "Besiegt Akolythin Nelesis und bringt ihren Leichnam zum Turm nahe des Skapliagrats.", progress = "Habt Ihr den Leichnam?", completion = "Ich muss gestehen, dass ich es genossen habe, wie Ihr die Selbstgefälligkeit aus Nelesis' Gesicht herausgeprügelt habt. Sie hat sich immer für so überlegen gehalten.\n\nAber genug gejubelt, wir haben etwas zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61741] = { id = 61741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklau", description = "Für den Abschluss des Illusionsrituals wird eine nicht unerhebliche Menge Anima benötigt. Diese Art Ressource liegt dieser Tage nicht einfach so herum, also müssen wir sie anderweitig abzweigen.\n\nDie Monstrositäten des Hauses der Konstrukte sind kürzlich mit animareicher Beute vom Schlachtzug gegen die Bastion zurückgekehrt.\n\nVerwendet den Maldrazitkristall in dem Paket, um genug Anima für unser Ritual zu extrahieren.", sourceObjective = "Entzieht der Kyrianerbeute im Haus der Rituale Anima, um damit den Maldrazitkristall aufzufüllen.", completion = "Das sollte ausreichen.\n\nLasst uns das Ritual vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61742] = { id = 61742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Tarnung", description = "Mithilfe meines Oculus sollte das Ritual zum Abschließen Eurer Tarnung eigentlich ganz einfach sein. Selbst <ein/eine:c> {class} wie Ihr sollte das hinbekommen.\n\nWenn Ihr bereit seid, haltet Ihr einfach den ermächtigten Kristall über den Leichnam von Nelesis. Mein Oculus wird dann den Rest erledigen.", sourceObjective = "Trefft Balmedar in der Halle der Klingen im Haus der Rituale.", completion = "Eine verblüffende Ähnlichkeit. Das könnte tatsächlich funktionieren.\n\nAlso, worauf wartet Ihr noch?", sourceObjectiveStatus = "unverified-source-field" }
quests[61743] = { id = 61743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück beim Meister", description = "Jetzt, wo Ihr Eure Tarnung habt und ich die Bestätigung Eurer Loyalität, solltet Ihr Euch bei Eurem neuen Meister melden.\n\nIhr findet Kel'Thuzad im Verlies der Seelen. Macht, was immer er Euch aufträgt, aber achtet darauf, ob dort alles mit rechten Dingen zugeht.\n\nMein Oculus wird Euch weiterhin begleiten. Auf diese Weise kann ich Euch unterstützen, wenn die Zeit gekommen ist.\n\nWir werden herausfinden, was dieser neue Baron tatsächlich vorhat.", sourceObjective = "Trefft Kel'Thuzad im Verlies der Seelen.", completion = "Ah, Ihr seid zurück. Ich gehe davon aus, dass das Ritual ein Erfolg war?\n\nKommt, wir haben einiges zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61744] = { id = 61744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan des Barons", description = "Ihr habt mir gute Dienste geleistet, Nelesis. Wenn für mich die Zeit gekommen ist, meinen rechtmäßigen Platz einzunehmen, werdet auch Ihr belohnt.\n\nBis dahin erwarte ich von Euch äußerste Hingabe und Verschwiegenheit.\n\nWir haben die Vorbereitungen fast abgeschlossen. Kommt, gehen wir ein Stück, dann werde ich Euch die Pracht unseres Werkes zeigen.", sourceObjective = "Begleitet Kel'Thuzad.", completion = "Es gilt, noch ein paar Aufgaben zu erledigen, bevor wir das Ritual abschließen können.\n\nIhr müsst sofort damit beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61745] = { id = 61745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Folianten", description = "Der Kyrianer wird zweifelsohne eine würdige Opfergabe für unser Ritual abgeben, aber die Magie seines Volkes erschließt sich mir nicht vollständig. Ich habe die Baronin Ninadar gebeten, eine Liste mit entsprechender Literatur zusammenzustellen, damit ich sicherstellen kann, dass mein Ritual den gewünschten Effekt hervorruft.\n\nWie Ihr wisst, neigt die Baronin dazu, ihre Position auszunutzen, also rechnet damit, dass Ihr im Gegenzug für ihre Zusammenarbeit ein paar schlichte Aufgaben erledigen müsst. \n\nKehrt zu mir zurück, wenn Ihr die Folianten bekommen habt, <Akolyth/Akolythin>.", sourceObjective = "Sprecht mit Baronin Ninadar im Grimoirium.", completion = "Kel'Thuzad scheint sich immer die gelehrigsten Haustierchen zu halten, nicht wahr?\n\nWas möchte der Baron denn dieses Mal von mir, Akolyth?", sourceObjectiveStatus = "unverified-source-field" }
quests[61746] = { id = 61746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberhafte Sammlung", description = "Eine der eher... lästigen Pflichten einer Herrin der Folianten ist der Abgleich und Erhalt unserer Schriftrollenbibliothek. Leider lassen sich viele der Akolythen ungebührlich viel Zeit bei der Rückgabe der ausgeborgten Exemplare. Aus diesem Grund muss ich sie dann persönlich aufsuchen und sie ihnen wieder abnehmen.\n\nDas ist natürlich eine absolut unwürdige Aufgabe für eine Baronin und vielmehr etwas für Lakaien wie Euch.\n\nAlso geht und bringt mir meine Schriftrollen zurück. Die Wahl der Mittel der Überzeugung steht Euch dabei frei.", sourceObjective = "Sammelt 6 überfällige Schriftrollen von nekrotischen Akolythen im Grimoirium ein.", progress = "Habt Ihr meine Schriftrollen gefunden?", completion = "Wundervoll. Kel'Thuzad's Haustierchen sind immer so verlässlich.\n\nWir sind hier fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[61747] = { id = 61747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberungen auf Abwegen", description = "Im Haus der Rituale wird fortwährend studiert. Jeden Tag werden neue Beschwörungen und Formeln entwickelt, um die Kunst der Nekromantie zu vertiefen.\n\nBei so viel Innovation kann man schon mal den Überblick verlieren. Um uns beim Katalogisieren der Fortschritte zu helfen, haben unsere Hexenmeister die Verwendung von verzauberten Federkielen und Pergamenten ermöglicht. Leider geraten diese vollständig außer Kontrolle, wenn sie nicht korrekt verwahrt werden.\n\nUnd natürlich wurden sie nicht korrekt verwahrt. Findet diese Hilfsmittel und bringt sie dahin zurück, wo sie hingehören.", sourceObjective = "Sichert 4 schelmische Federkiele und 6 irrende Folianten im Grimoirium.", progress = "Verzauberte Federkiele sammeln sich doch nicht von selbst, oder?", completion = "Viel besser!\n\nIch ertrage einfach keine Unordnung im Grimoirium.", sourceObjectiveStatus = "unverified-source-field" }
quests[61748] = { id = 61748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Halle der Folianten", description = "Also gut, Ihr sollt Eure Liste haben. Die Ausgaben, nach denen Ihr sucht, findet Ihr in der Halle der Folianten.\n\nUnd jetzt seid ein gutes Haustierchen und lauft zurück zu Eurem Meister.", sourceObjective = "Sammelt die benötigten Ausgaben in der Halle der Folianten und bringt sie Kel'Thuzad im Verlies der Seelen.", progress = "Ihr seid zurück? Habt Ihr meine Folianten?", completion = "Ah, ja, damit kann ich arbeiten.\n\nIch werde aber eine Weile brauchen, um sie zu studieren. In der Zwischenzeit habe ich weitere Aufgaben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61749] = { id = 61749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforderliche Zutaten", description = "Ihr seid Euch sicherlich bewusst, dass ein solch komplexes Ritual verschiedene Reagenzien erfordert. Ich habe Schnitzer Jor'dan gebeten, alles vorzubereiten, was ich benötige.\n\nSucht ihn im Reagenzium auf und bietet ihm jede nötige Hilfe an.", sourceObjective = "Sprecht mit Jor'dan dem Mächtigen im Reagenzium.", completion = "Ihr seid Kel'Thuzads Akolyth, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[61750] = { id = 61750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Waldes", description = "Das Herz eines Schleierflügels, das der Baron angefordert hat, ist nicht leicht zu beschaffen.\n\n<Jor'dan deutet auf das Chaos in der Nähe.>\n\nWie Ihr seht, hatte einer unserer Zauberer Schwierigkeiten beim Bändigen der Bestie. Es tut mir leid, Euch davon in Kenntnis setzen zu müssen, dass unser einziges Exemplar entwischt ist.\n\nWeit kann es aber nicht gekommen sein. Folgt seinen Spuren. Ihr solltet es einholen und das Herz selbst beschaffen können.\n\nIch kann Euch versichern, dass der Baron sein Ritual nicht ohne es durchführen kann.", sourceObjective = "Beschafft das Herz eines Schleierflügels vom flüchtigen Schleierflügel im Haus der Rituale.", progress = "Habt Ihr den Schleierflügel gefunden?", completion = "Dieses Exemplar sollte genau richtig für das Ritual des Barons sein.\n\nIch werde es in sein Paket geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[61751] = { id = 61751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporensuche", description = "Ich brauche Eure Hilfe beim Sammeln eines weiteren Reagenzes für Euren Meister. Diese Sporenbüschel, die er haben will, sind normalerweise leicht zu bekommen, erfordern nun jedoch etwas Einsatz.\n\nAls der Schleierflügel nämlich durch das Reagenzium gewütet ist, hat er mehrere Käfige der Pestrochen beschädigt, von denen wir die Büschel gewinnen.\n\nIhr müsst sie mit... konventionelleren Methoden sammeln.\n\nDie Büschel sind jedoch sehr zart, beschädigt sie also nicht, wenn Ihr die Kreaturen unterwerft.", sourceObjective = "Gewinnt 6 intakte Sporenbüschel von entflohenen Pestrochen im Reagenzium.", progress = "Habt Ihr die Sporenbüschel?", completion = "Das sollte genügen.\n\nIch werde die Reagenzien zusammenstellen, damit sie schnellstens zu Eurem Meister gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61752] = { id = 61752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Reagenz", description = "Ich habe die meisten der verbleibenden Reagenzien für die Liste Eures Meisters zusammengetragen. Es fehlt nur noch die spezielle Lieferung, die er aus Oribos erwartet.\n\nDie Mittler müssen diese Lieferung noch zustellen. Wenn sie ankommt, hat er alle Zutaten für den Abschluss des Rituals.", sourceObjective = "Bringt das Bündel mit Reagenzien zu Balmedar im Haus der Rituale.", progress = "Mal schauen, was wir hier haben.", completion = "Ich verwahre das erst mal für Euch.\n\nIch möchte, dass Ihr Euch um diese Lieferung kümmert!", sourceObjectiveStatus = "unverified-source-field" }
quests[61753] = { id = 61753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosiver Plan", description = "Die Mittler handeln mit den exotischsten und wirkmächtigsten Waren. Wenn Kel'Thuzad solche Reagenzien von ihnen anfordert, muss er ein für das Haus der Rituale ungewöhnlich mächtiges Ritual planen.\n\nDieses mysteriöse Reagenz könnte der Schlüssel zu Kel'Thuzads Plan sein. Wir müssen diese Lieferung aus Oribos abfangen.\n\nIch war so frei, eine alchemistische Bombe zusammenzustellen. Verwendet sie für einen Überfall auf die Karawane und sichert das, was sie transportieren.", sourceObjective = "Verwendet den alchemistischen Sprengstoff für einen Überfall auf die Mittlerkarawane am Skapliagrat.", progress = "Die Karawane trifft jeden Moment ein. Beeilt Euch jetzt!", completion = "Gut gemacht.\n\nJetzt müssen wir schnell agieren, bevor wir entdeckt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61754] = { id = 61754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Kiste auf der anderen lassen", description = "Die Explosion wird sicherlich ein paar Leute vom Haus der Rituale herbeilocken. Wir müssen schnell handeln.\n\nDurchsucht die Trümmer nach allem, was außergewöhnlich aussieht. Möglicherweise ist Kel'Thuzads Reagenz nicht einfach auszumachen.", sourceObjective = "Durchsucht die Kisten der Mittler nach Kel'Thuzads speziellem Reagenz.", completion = "Die Runen auf dieser Klinge... es sind typische Zeichen der Beherrschungsmagie!\n\nDas ist nicht gut, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61755] = { id = 61755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schweigen der Mittler", description = "Wir dürfen nicht zulassen, dass Kel'Thuzad herausfindet, wer seine Lieferung aufgehalten hat.\n\nNiemand darf von dem berichten, was hier passiert ist.", sourceObjective = "Tötet 8 Mittlerzeugen am Skapliagrat.", completion = "Ihr habt die Wachen ausgeschaltet? Gut.\n\nEs gibt jetzt dringendere Dinge zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61756] = { id = 61756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Scheitern verurteilt", description = "Jetzt kommt alles zusammen. Der Kyrianer, die Pfade der Ersten und jetzt Herrschaftsrunen?\n\nKel'Thuzad will sich Zugang zum Schlund verschaffen!\n\nDas dürfen wir nicht zulassen! Es gibt gute Gründe dafür, warum der Zugang von den Schattenlanden zum Schlund versiegelt ist. Dieses Fluttor zu öffnen, könnte katastrophale Folgen haben!\n\nDer Baron ist viel zu mächtig. Wir können ihn nicht direkt angreifen Also müssen wir stattdessen sein Ritual unterbinden. Kehrt mit den Reagenzien zu ihm zurück. Ich werde ein paar \"Modifikationen\" vornehmen, die seinen verhängnisvollen Plänen ein Ende bereiten.", sourceObjective = "Bringt das Bündel mit \"modifizierten\" Reagenzien zu Kel'Thuzad im Verlies der Seelen.", progress = "Ah, da seid ihr ja wieder, Akolyth. Was habt Ihr für mich?", completion = "Ich sehe, dass Ihr die Reagenzien von Jor'dan bekommen habt und... Moment. Was haben wir denn hier?\n\nDas ist ja beeindruckend, dass Ihr die Lieferung von den Mittlern sichern konntet, während dies meinen Hexenmeistern nicht gelungen ist!\n\nIhr erweist Euch als äußerst nützlich, Akolyth!", sourceObjectiveStatus = "unverified-source-field" }
quests[61757] = { id = 61757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertappt", description = "Nun, da es Euch gelungen ist, das fehlende Reagenz zu beschaffen, halte ich es für nur gerecht, dass Ihr mir beim finalen Ritual assistiert!\n\nIch kann Euch versichern, dass Ihr durch diese Beschwörung zu <einem vollwertigen Zauberer/einer vollwertigen Zauberin> des Hauses aufsteigen werdet!\n\nDie Vorbereitungen sind bereits abgeschlossen, wir können anfangen, sobald Ihr bereit seid.", sourceObjective = "Helft Kel'Thuzad dabei, sein Ritual zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61758] = { id = 61758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvisierte Mittel", description = "Es muss einen Weg geben, wie wir uns aus diesen Zellen befreien können.\n\nIch sehe nichts, was ich hier nutzen könnte. Sucht Eure Zelle nach etwas ab, das uns bei der Flucht helfen könnte.", sourceObjective = "Sucht Eure Zelle nach etwas ab, das Euch zur Flucht verhelfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[61759] = { id = 61759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Um eine Hand zu animieren, braucht es nur etwas Nekromantie. Unglücklicherweise seid Ihr der Hand am nächsten, also müsst Ihr sie befehligen.\n\nWenn Ihr bereit seid, werde ich die Hand reanimieren. Wenn Ihr die Kontrolle über sie erlangt habt, verwendet Ihr sie, um an dem Hebel am Ende der Halle zu ziehen.\n\nIst doch eigentlich ganz einfach, oder?", sourceObjective = "Bewegt die reanimierte Hand zum Ende der Halle und betätigt den verrosteten Hebel.", completion = "Wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[61760] = { id = 61760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Demaskierung des Verräters", description = "Wir dürfen keine Zeit verschwenden und müssen sofort die Markgräfin vor Kel'Thuzads Verrat warnen. Seine rücksichtslose Anwendung verbotener Kräfte könnte das Haus und noch mehr in den Untergang stürzen!\n\nLasst uns diesen Machenschaften ein Ende bereiten!", sourceObjective = "Stellt Kel'Thuzad in der Halle der Zauberkunst.", progress = "Wir müssen Kel'Thuzad aufhalten, bevor es zu spät ist!", completion = "Ich hatte nicht erwartet, dass wir diese Begegnung unbeschadet überstehen würden.\n\nIhr seid wirklich fähig, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[61761] = { id = 61761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der bessere Teil der Tapferkeit", description = "Wir haben keine andere Wahl. Wir müssen sofort den strategischen Rückzug antreten. Kel'Thuzad hat sich in seiner Nekropole zu stark verbarrikadiert. Und wenn Ninadar seine Verbündete ist, dann hat er das Haus der Rituale fest im Griff.\n\nUm die Markgräfin zu retten, braucht es jetzt schon eine ganze Armee.", sourceObjective = "Kehrt zum Sitz des Primus zurück.", completion = "Die Markgräfin wurde gefangen genommen? Dann hat Kel'Thuzad die Kontrolle über das Haus!\n\nDas ändert die Lage.", sourceObjectiveStatus = "unverified-source-field" }
quests[61762] = { id = 61762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen schlaueren Gräber erschaffen", description = "Wenn dieser Gräber mit Euch und Temel bei so 'nem schicken Hof mitmachen soll, muss er was Besonderes werden...\n\nKlüger. Stärker. Besser darin, sich zu entschuldigen, wenn er Tische mit Erfrischungen umwirft und Anima über die arme Herzogin kippt...\n\nIch hab 'ne Idee! Der Mittlertyp auf dem Nachtmarkt wollte mir so 'n besonderes Getränk verkaufen. Kaja'Extrem oder so.\n\nSoll wohl gut für die Birne sein? Also genau, was wir brauchen.\n\nNehmt diese Sengpilze, der Mittler liebt die. Ihr müsst allerdings wissen, dass er seine Preise wöchentlich ändert.", sourceObjective = "Kauft eine Flasche Kaja'Extrem von Ta'tru auf dem Nachtmarkt.", progress = "Habt Ihr das Kaja'Extreme?", completion = "Also, {name}, ran an die Drecksarbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[61763] = { id = 61763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Helfer ausgraben", description = "So, jetzt geht's an Gräbermachen.\n\nGenau wie mit dem Lulatsch vorhin!\n\nAber dazu brauchen wir keinen Bindungsstein oder drei andere Gräber. Ihr müsst einfach nur Sachen in den Morast werfen!\n\nIst also das gleiche.\n\nMit der kajaversetzten Gräbermischung, die ich extra für Euch gemacht habt, kann da nix schiefgehen.\n\nSchmeißt das in die Schlammlache und begrüßt Euren neuen Gräberbutler!", sourceObjective = "Kippt die kajaversetzte Gräbermischung in die Schlammlache, um Euren Gräberbutler herzustellen.", completion = "Es hat funktioniert! Das war mir natürlich klar. Wie nennen wir den Kerl jetzt... aber erst entlasse ich ihn, damit Ihr die Verbindlichkeit des Vertrages testen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[61764] = { id = 61764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Namen ausgraben", description = "He, warum nennt Ihr mich nicht bei meinem richtigen Namen? Moment, an den erinner' ich mich gar nicht. Bedeutet das, ich habe Amnesien? Oh nein, ich hab keinen Namen, helft mir bitte!", sourceObjective = "Sprecht mit Eurem Helfer und sucht Euch einen Namen aus.", completion = "Oh ja, der Name passt gut zu meiner Persönlichkeit. Zumindest glaub ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[61765] = { id = 61765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutze sehen und entfernen", description = "Die in der Ferne aufragende Zitadelle wird von gefährlichen Mauern beschützt, aber die größten Gefahren sind für die Augen eines Sterblichen nicht erkennbar.\n\nDie Schlundgebundenen haben überall in der Verdammnisfestung unsichtbare Schutzrunen platziert. Diese Fallen haben schon viele Eindringlinge kalt erwischt.\n\nDie Runen können entfernt werden, aber nur, wenn man sie sehen kann. Einer ihrer Seelenumhänge sollte Euch das ermöglichen.\n\nViel Glück.", sourceObjective = "Stehlt einen Seelenumhang des Assassinen und entfernt 4 Schutzrunen in der Verdammnisfestung im Schlund.\n\nEmpfohlene Spieleranzahl [3]", progress = "Sind die Schutze weg? Ich möchte dringend die Überwachung unseres Feindes wieder aufnehmen.", completion = "Ich hoffe, Ihr habt Euch nicht weiter umgesehen, während Ihr den Seelenumhang getragen habt? Er kann einen fürwahr schreckliche Sachen sehen lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[61766] = { id = 61766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausgemachte Haushaltshilfe", description = "Jeder gute Festherold benötigt einen Assistenten. Und darum habe ich Euch!\n\nAber jeder gute Festheroldassistent... braucht auch einen Assistenten.\n\nUnd darum habe ich vom Prinzen die Erlaubnis eingeholt, dass Ihr Euren eigenen Gräberbutler erschaffen dürft. Er kann als Sicherheitspersonal beginnen, während wir uns bei den Gäste einschmeicheln und das notwendige Lesematerial beschaffen, um ihn in den sozialen Verhaltensweisen der verschiedenen Reiche zu schulen. Er wird den ganzen Hof in kürzester Zeit unterhalten.\n\nNein, nichts zu danken. Das habt Ihr Euch verdient!", sourceObjective = "Trefft Rendel im Gräberwald, um einen Gräberbutler zu erschaffen.", completion = "Bereit, Euch die Hände schmutzig zu machen?\n\nGräber zu machen, ist dreckige Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[61767] = { id = 61767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gefährliche Reise", description = "Mograine hat das Haus der Auserwählten zusammengerufen, um Markgraf Gharmal und sein Haus der Konstrukte anzugreifen. Mit jedem Tag werden sie stärker, und das könnte unsere letzte Chance sein.\n\nWir stoßen auf dem Schlachtfeld zu ihnen. Die Gefallenen meines Tempels werden Gerechtigkeit erfahren, und auch Mograines gefallene Leute.\n\nTreffen bei der Spinnenwacht in den nördlichen Gebieten von Maldraxxus. Von dort aus geht es weiter.", sourceObjective = "Trefft Xandria bei der Spinnenwacht in Maldraxxus.", completion = "Jetzt können wir zu unseren neuen Verbündeten stoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61768] = { id = 61768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam stärker", description = "Wir treffen Baronin Draka auf der Zerekriss über dieser Position. Vertraut in der anstehenden Schlacht auf die Entscheidungen unserer Verbündeten. Wahrer Mut bedeutet zu wissen, wann man sich auf die Weisheit der anderen verlassen sollte.\n\nDer Plan ist einfach. Die Flanken erledigen, damit Gharmals Streitkräfte uns bei unserem wahren Ziel nicht im Weg stehen. Dann greifen wir den Markgrafen selbst an.\n\nScheitern wir, dann im Namen der Gerechtigkeit.", sourceObjective = "Fliegt mit Xandria in die Nekropole Zerekriss.", completion = "Willkommen auf der Zerekriss, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61769] = { id = 61769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen und Kämpfen", description = "Alexandros und Emeni werden den Angriff der Auserwählten auf das westliche Tor anführen.\n\nIhr und Xandria werdet unsere Truppen gegen das östliche Tor führen. Sichert das Gebiet und eliminiert jeglichen Widerstand.\n\nWenn beide Flanken gesichert sind, können wir Gharmal direkt angreifen.", sourceObjective = "Fliegt mit Xandria zum Haus der Konstrukte.", completion = "Dieser Ort ist voller Schrecken... Schrecken, die wir auslöschen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61770] = { id = 61770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlächter der Bastion", description = "Haben diese Scheusale meinen Leuten Gnade gewährt, als sie die Bastion angegriffen haben? Als sie meine Brüder und Schwestern auseinandergerissen und benutzt haben, um noch mehr von diesen... Dingern zu erschaffen?!\n\nNein! Die Schlächter der Bastion haben an diesem Tag ihre Absichten offenbart!\n\nSie verdienen nichts anderes als die ewige Finsternis, die auf sie wartet. Sorgt dafür, dass sie sie zu sehen bekommen!", sourceObjective = "Tötet 10 Truppen des Hauses der Konstrukte in der Auftrennungskammer.", completion = "All dieses Blutvergießen wird sie nicht zurückbringen... Aber es könnte anderen das gleiche Schicksal ersparen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61771] = { id = 61771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit von oben", description = "Unsere Truppen können nicht vollständig auf dieses Gebiet niederstoßen, solange die Kristalle der Markgräfin den Himmel mit vernichtenden Angriffsschlägen eindecken.\n\nDie schändlichen Schlächter der Markgräfin arbeiten sogar in diesem Moment daran, die verbleibende Anima aus den Kyrianern, die sie bei ihrem Angriff auf die Bastion entführt haben, zu extrahieren. Wir müssen sofort angreifen.\n\nIch werde Euch mit den Flammen des Mutes verzaubern, damit Ihr die Kristalle markieren könnt. Sobald sie markiert sind, werde ich sie aus der Ferne zerstören.", sourceObjective = "Zerstört 5 Maldrazitkerne.", completion = "Ihr habt hier große Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[61772] = { id = 61772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Entwicklungen", description = "<Der zerfledderte Entwurf scheint von dem verstorbenen Chirurgen Fleischnaht aufgesetzt worden zu sein.>\n\n... kyrianisches Fleisch verbessert Stärke, Gehorsam und Geschicklichkeit doppelt! Was für ein Potenzial!\n\nWenn jetzt bei Versuchsobjekt eins-drei-fünf endlich die Schwingentransplantation klappt...\n\n<So geht es eine Weile weiter. Ihr solltet es zu Artemede bringen.>", sourceObjective = "Bringt den abscheulichen Entwurf zu Artemede vor der Halle der Ketten.\n\nBereitgestellter Gegenstand:", completion = "Gewährt mir einen Moment, um das zu lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61773] = { id = 61773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgestiegen", description = "Obwohl wir das Erschaffen weiterer Kolosse verhindert haben, atmet eine ihrer scheußlichsten Schöpfungen immer noch. Sie entstand aus einer der gequältesten Seelen, die sie aus meinem Tempel geraubt haben.\n\nWährend ich über ihre Reihen flog, hörte ich, wie die Chirurgen ihren Namen über dem Schlachtenlärm hinweg riefen: Kummerklinge. Blasphemie gegen alles, wofür die Kyrianer stehen, und eine Abscheulichkeit, die jeder Beschreibung spottet.\n\nMarkiert sie mit den Flammen des Mutes, und wir helfen Euch, sie zu zerstören.", sourceObjective = "Tötet Kummerklinge die Abscheulichkeit.", completion = "Möge unser Sieg ihnen Frieden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61774] = { id = 61774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Lesen verbrennen", description = "Die von Euch geborgene Schriftrolle beschreibt detailliert alle möglichen entsetzlichen Wege, um gefallene Kyrianer in Gharmals Monstrositätskonstrukte zu \"integrieren\".\n\nGleichzeitig ist sie aber auch unvollständig. Es muss noch mehr davon bei den restlichen Anhängern von Fleischnaht geben.\n\nIch habe gesehen, wie sich einige Chirurgen und ihre Lakaien kurz vor unserer Ankunft in die Halle der Ketten zurückgezogen haben. Ich vermute, sie besitzen weitere dieser Schriftrollen.\n\nWir müssen dafür sorgen, dass sie nie wieder gelesen werden.", sourceObjective = "Sammelt 6 von Fleischnahts Entwürfen.", progress = "Dieses grässliche Werk muss vernichtet werden.", completion = "Gut gemacht. Ich werde mich persönlich darum kümmern, dass sie vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61775] = { id = 61775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein jähes Ende", description = "In der Halle der Ketten warten noch mehr Monstrositäten, die fast vollendet sind. In diesem Moment arbeiten die Truppen des Markgrafen fieberhaft daran, die letzten Stücke Fleisch an ihre scheußlichen Visagen zu transplantieren.\n\nStellen sie ihre Arbeit fertig, werden die von uns zerstörten Konstrukte in der letzten Schlacht von geringer Bedeutung sein. Unsere Flanke wird von einer neuen Welle des Schreckens überrannt, und die Schlacht ist verloren.\n\nDas darf nicht passieren. Zerstört alle Monstrositäten, denen Ihr begegnet.", sourceObjective = "Zerstört 6 unbelebte Schlächter.", completion = "Jede unvollendete Monstrosität ist ein Gegner weniger, wenn wir Gharmal gegenüber stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61776] = { id = 61776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Westfront", description = "Alexandros und unsere Maldraxxiverbündeten brauchen Verstärkung am Westtor, auf der gegenüberliegenden Flanke des Markgrafen. Sie werden nicht mehr lange durchhalten!\n\nUnsere Truppen werden unsere Stellung hier verstärken und in Richtung Gharmal vorstoßen. Wir müssen so schnell wie möglich zu Mograine. Ohne beide Flanken gibt es keine Aussicht auf den Sieg.", sourceObjective = "Fliegt mit Kynthia und meldet Euch bei Alexandros am Flickenhof.", completion = "Ich bin froh, dass Kynthia Euch so schnell gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[61777] = { id = 61777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge aufladen", description = "Wir können nicht vorrücken, solange die Kolosse unsere Position bombardieren! Ich habe die angegriffen, die uns am nächsten sind, aber konventionelle Waffen können ihren verzauberten Häuten nichts anhaben.\n\nGlücklicherweise habe ich aber eine Idee.\n\nSo wie es aussieht, kann Eure alte Runenklinge ihnen nichts anhaben, aber wenn Ihr Gharmals verstärkte Truppen auslöschen und ihre Essenz auf Eure Klinge übertragen könntet...", sourceObjective = "Ladet Eure Runenklinge auf, indem Ihr feindliche Konstrukte im Flickenhof tötet.", completion = "Das ist nur ein Versuch, aber es könnte funktionieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[61778] = { id = 61778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftherrschaft", description = "Gharmals Rocs verfügen über die Luftherrschaft und greifen unsere vorrückenden Truppen an. Wir können die Zerekriss nicht in Position bringen, bis sie ausgeschaltet sind!\n\nIch würde mich ja selbst um sie kümmern, aber meine Flugkünste sind eher dürftig. Mangelnder Gleichgewichtssinn!\n\nNehmt meinen Reiterhaken und schwingt Euch auf einen Roc. Wenn Ihr draufsitzt, dann schlagt einfach zu, bis es erledigt ist.", sourceObjective = "Holt 6 kampfvernähte Rocs vom Himmel.", completion = "Ich habe ihre Schreie bis hierher gehört. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[61779] = { id = 61779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Absichten", description = "Meine Spione haben mehrere Astralprojektoren entdeckt, die Markgraf Gharmal nutzt, um seine Truppen im Flickenhof zusammenzurufen.\n\nIch will nicht, dass ein Schwarm rasender Konstrukte in der letzten Schlacht auf uns niederprasselt. Ihr seht sicherlich den Vorteil darin, ihren Eifer zu dämpfen.\n\nKümmert Euch darum, dass diese Projektoren zerstört werden. Wir glauben, dass sie im Hof sind.", sourceObjective = "Zerstört die südwestlichen, nordwestlichen und nordöstlichen Astralprojektoren.", completion = "Gharmals Einfluss ist hier tief verwurzelt, aber er wird dank Eurer Anstrengungen schneller verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61780] = { id = 61780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht des Auserwählten", description = "Die Zerekriss ist fast in Position. Wir müssen jetzt zuschlagen!\n\nWir müssen Gharmal gemeinsam aus seiner Deckung locken. Schwingt Euch zu mir auf den Roc, und wir lassen die Kolosse die Macht Eurer Runenklinge spüren.\n\nDer Markgraf kann ihre Tode nicht ignorieren. Sobald er seinen elenden Turm verlässt, können wir ihn endgültig erledigen.", sourceObjective = "Zerstört die Gallblähkolosse.", completion = "Welche Macht! Gharmal bleibt keine Wahl, als sich uns zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61781] = { id = 61781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist das Ende", sourceObjective = "Trefft Euch mit Xandria nahe der zentralen Kammer des Hauses der Konstrukte.", completion = "Die Zeit ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61782] = { id = 61782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streben nach Gerechtigkeit", description = "Draka ist bereit, die Kräfte der Zerekriss auf Gharmal zu entfesseln. Wir müssen ihr nur etwas Zeit verschaffen, damit sie die Waffe fokussieren kann.\n\nWas wir jetzt tun, tun wir für uns alle. Die Bastion und Maldraxxus haben viele Leben an diesen Feind verloren.\n\nEr wird nicht leicht zu besiegen sein, aber mit unseren vereinten Kräften werden wir ihn richten!", sourceObjective = "Besiegt Markgraf Gharmal.", completion = "Unsere Gefallenen können endlich in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61783] = { id = 61783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kieferknacker", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61784] = { id = 61784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klippen der Bastion", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61785] = { id = 61785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erwarteter Besucher", description = "Ein Alexandros Mograine von Maldraxxus trifft sich mit dem Paragon des Mutes bei der Archonhöhe. Xandria bittet Euch, zu ihnen zu stoßen.\n\nDie beiden haben kürzlich zusammengearbeitet, um einen aufkeimenden zweiten Angriff auf den Tempel des Mutes zurückzuschlagen. Xandria scheint ihm zu vertrauen, also haben wir ihm Zugang zur Festung gewährt... fürs Erste.\n\nIch vermute, sie bleiben nicht lange hier. Ihr solltet Euch beeilen.", sourceObjective = "Sprecht mit Xandria bei der Archonhöhe.", completion = "Gut. Jetzt kann unsere Mission beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61786] = { id = 61786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Steinkopf", sourceObjective = "Euer \"bester Kumpel\" Steinkopf besteht darauf, für Euch zu kämpfen, {name}.\n\n. Wir finden bestimmt Verwendung für seine Talente. Aber natürlich nichts allzu Kompliziertes.", sourceObjectiveStatus = "unverified-source-field" }
quests[61787] = { id = 61787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikroverteidiger", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61788] = { id = 61788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Simone", sourceObjective = "Eure Taten für Revendreth ziehen viel Aufmerksamkeit auf sich, {name}.\n\n. Simone hat angeboten, der Sache ihr Fachwissen über die Spiegel des Glutdistrikts zur Verfügung zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61789] = { id = 61789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Verlorene Sibylle", sourceObjective = "Theotar hat die Verlorene Sibylle nachdrücklich empfohlen.\n\nUnd sie hat uns einen Beutel mit Steinlegionköpfen und zwei Kanister mit Anima bei ihrer Ankunft überlassen. Sie scheint also schon auf unserer Seite zu kämpfen.\n\nMal sehen, was sie mit einigen Verbündeten anfangen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[61790] = { id = 61790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Vulca", sourceObjective = "Jeder, der den Glutdistrikt so lange wie Vulca überlebt, ist hart wie Stein.\n\nSie hat ganz sicher den ein oder anderen unerwarteten Trick zu bieten, mit dem sie uns helfen kann, die Feinde auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61791] = { id = 61791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thenias treue Gefährten", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61792] = { id = 61792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Bogdan", sourceObjective = "Eure Loyalität gegenüber Revendreth steht außer Frage, {name}.\n\n. Bogdan hat angeboten, sich von Theotars Diensten freistellen zu lassen, und wird Euch helfen, wo er nur kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[61813] = { id = 61813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valinor, das Licht der Äonen" }
quests[61814] = { id = 61814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurgash Schlammborn" }
quests[61815] = { id = 61815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oranomonos die Immersprießende" }
quests[61816] = { id = 61816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortanis" }
quests[61839] = { id = 61839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Unterholz nagen", description = "<Der kleine Fresser knabbert hungrig an Euren Hacken und will von Euch beschützt werden. Vielleicht mag er einige der Pflanzen hier?>", sourceObjective = "Sammelt Endmorastrankenwurzeln.", progress = "Sammelt Endmorastrankenwurzeln für Euren kleinen Fresser.", completion = "<Der Fresser kaut schmatzend an der Rankenwurzel und schaut Euch zwischen jedem Bissen neugierig an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61840] = { id = 61840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rankenwurzeln auf der Speisekarte", description = "<Der kleine Fresser taucht wieder auf und Ihr seht deutlich, dass er nach mehr Endmorastrankenwurzeln sucht.>", sourceObjective = "Sammelt Endmorastrankenwurzeln.", progress = "Sammelt Endmorastrankenwurzeln für Euren kleinen Fresser.", completion = "<Ihr könnt gerade noch Eure Hand zurückziehen, als sich der Fresser das Bündel schnappt. Euch fällt unwillkürlich auf, dass er zu wachsen scheint. Zwischen Bissen spuckt er etwas aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61841] = { id = 61841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Schleim um Nichts" }
quests[61842] = { id = 61842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rankenwurzeln sind nicht gut genug", description = "<Der Fresser ist gewachsen und beäugt eine Rankenwurzel, auf die Ihr zeigt. Ihr bemerkt unterschwellige Aggression in seinem Blick, als Ihr ihm die Wurzel wieder anbietet. Sehnsüchtig schaut er zu den Verschlingermilben in der Nähe.>", sourceObjective = "Sammelt durchströmte Endmorastfrüchte.", progress = "Sammelt durchströmte Endmorastfrüchte von den Verschlingermilben im Endmorast oder im Fluchwald.", completion = "<Als Ihr die Früchte vor dem Fresser ablegt, verschlingt er jede im Ganzen. Es schmeckt ihm sichtlich. Er schaut Euch an, bemerkt, dass Ihr nicht esst, und lässt ein paar für Euch fallen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61844] = { id = 61844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungriger, hungriger Fresser", description = "<Die Fresserbrut springt an Euch hoch, hat dabei aber nur die Verschlingermilben im Blick.>", sourceObjective = "Sammelt durchströmte Endmorastfrüchte.", progress = "Sammelt durchströmte Endmorastfrüchte von den Verschlingermilben im Endmorast oder im Fluchwald.", completion = "<Als Ihr die Früchte fallen lasst, schnappt der Fresser sie sich in der Luft, noch bevor sie den Boden berühren. Ihr seht, dass der Fresser Euch einen kleinen Gegenstand mitgebracht hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61845] = { id = 61845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edikt der Verdammnis: Verschlinger", description = "Die Infusion von Anima in Revendreth hat zu einem Wiederaufleben des Verschlingerbefalls geführt. Diese Weltenfresser müssen eliminiert werden.\n\nAuf Anordnung von Prinz Renathal und dem rechtmäßigen Hof der Ernter verhängt dieses Edikt die Verdammnis über diese Entartungen.\n\nErfüllt die Vernichtungsquote in Revendreth und erhaltet eine Belohnung, die Eurer Leistung entspricht.", sourceObjective = "Zerstört 20 Verschlinger in Revendreth.", completion = "Verschlinger. Dreckige Entartungen. Wir hätten ihr Aufkommen als Zeichen des Endes aller Tage erkennen müssen.\n\nIhr habt unseren Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61846] = { id = 61846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edikt der Verdammnis: Fleddermäuse", description = "Die neuerliche Animadurchdringung der Region hat dazu geführt, dass weit mehr Fleddermäusen belebt werden, als auch nur Ansatzweise gewollt sein kann.\n\nAuf Anordnung von Prinz Renathal und dem rechtmäßigen Hof der Ernter verhängt dieses Edikt die Verdammnis über die Fleddermäuse in Revendreth. \n\nIgnoriert die Fleddermäuse, die für Transportzwecke benutzt werden oder besonderen Pflichten nachgehen, aber tötet alle in den wilderen Regionen des Reichs. Euch winkt eine Belohnung.", sourceObjective = "Zerstört 25 Fleddermäuse in Revendreth.", completion = "Ah, gut gemacht. Fleddermäuse können nützliche Wesen sein, wenn sie ihrem vorgesehenen Zweck nachgehen. Aber unüberwacht und ungezähmt werden sie zu Raubtieren, die die mit uns um die wenigen Seelen, die in unserer Obhut verbleiben, konkurrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[61847] = { id = 61847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällige Läuterung", description = "Viele Pflichten eines Steingeborenen wurden von Denathrius' Plänen fallengelassen. \n\nEine solche Pflicht ist die Eliminierung von Manifestationen. Der Prozess, den Venthyr nutzen, um Anima aus einer Seele zu extrahieren, ist unsauber und führt oft zur Manifestation ungelöster Angelegenheiten. \n\nDiese Wesen sind gefährlich, ihnen kein Einhalt geboten wird, und werden dank Eurer Animawiederbelebung in diesem verdorrten Land immer häufiger.\n\nZerstört alle Manifestationen, die Euch auf Patrouille in Revendreth begegnen, und ich werde Euch für Eure Mühen entlohnen.", sourceObjective = "Zerstört 30 Manifestationen in Revendreth.", completion = "Ich weiß Eure Anstrengungen zu schätzen. \n\nWenn dieser Konflikt beigelegt ist, sollte die Steinlegion wieder ihre edle Bestimmung aufnehmen und Revendreth beschützen, anstatt den finsteren Launen von Denathrius und seinen Verbündeten nachzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61848] = { id = 61848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edikt der Verdammnis: Sündensteingolems", description = "Auf Anordnung des rechtmäßigen Hofs der Ernter wird ein Edikt der Verdammnis über jegliche Sündensteingolems verhängt, die sich innerhalb des Reiches zu gefährlichen Größen verbunden haben.\n\nDiese Wesen sind Manifestationen der ungelösten Sünden unerlöster Seelen, die in den Schlund verbannt wurden. Die jüngst auftretende Animadurchdringung der Region hat sie gefährlich stark gemacht.\n\nMerzt sie aus, dann winkt Euch eine Belohnung.", sourceObjective = "Zerstört 4 Sündensteingolems in Revendreth.", completion = "Ihr erledigt die Arbeit, mit der einst in besseren Zeiten die Steinlegion beauftragt war. Wir sind Euch dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[61849] = { id = 61849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biss um Biss", description = "Also, Ihr müsst ja eh ein paar Venthyr erledigen und ich bin ganz heiß auf ein paar Trophäen.\n\nEs ist nämlich so, dass die Venthyr es lieben, mich anzuknabbern, auch wenn man mir das nicht ansieht. Ich weiß nicht, was die für dunkle Gewohnheiten mit durch den Schleier geschleppt haben, aber ich hab keine Lust mehr, das Appetithäppchen für die zu spielen.\n\nWenn Ihr schon dabei seid, die Venthyr aus Euren... ganz eigenen Gründen zu töten, könntet Ihr mir doch gleich ein paar ihrer Fangzähne mitbringen.\n\nEs gibt auch eine Belohnung für die Beißerchen!", sourceObjective = "Sammelt 40 Venthyrfangzähne.", progress = "Das wird langsam eine schöne Sammlung.", completion = "Besten Dank. Das betrachte ich mal als \"Wiedergutmachung\", wie die Blutsauger das nennen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61851] = { id = 61851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Farbauswahl", description = "Ja, diese Schlammlache hat alles, was wir brauchen, um Euren Gräberbutler herzustellen.\n\nWir machen für Euch einen ganz besonderen. Maßgeschneidert, wie die Blutsauger sagen würden.\n\nAber erst müsst Ihr die Farbe wählen. Uns Gräber gibt es in allen möglichen Drecksfarben.\n\nSchaut Euch die anderen Gräber an und sagt mir dann, welche Farbe Euer Butler haben soll.\n\nWir können Gräber auch nachkolorieren, aber das ist keine schöne Sache.\n\n<Rendel erschauert bei dem Gedanken.>", sourceObjective = "Schaut Euch bei den Gräbern in der Nähe die möglichen Farben an und teilt Rendel dann mit, welche Farbe Ihr wünscht.", completion = "Ich bereite die Pigmente für Euch vor, aber für diesen Gräberbau brauchen wir noch was Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[61852] = { id = 61852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Wächterin Kota", sourceObjective = "Hallo nochmal, {name}. Es ist gut zu sehen, dass Ihr so interessiert an den Angelegenheiten des Ardenwalds seid.\n\nDie ehrenhafte Wächterin Kota hat sich bereit erklärt, als Teil ihrer Pflichten den Hain von Tirna Vaal zu beschützen.\n\nGemeinsam werdet Ihr die fortlaufende Sicherheit des Waldes gewährleisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61853] = { id = 61853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Te'zan", sourceObjective = "Der Wald ist immer hilfsbedürftig, {name}.\n\nTe'zan ist so temperamentvoll wie eh und je, und vielleicht wird eine gesunde Dosis Verantwortung seinem Leben nach dem Tod etwas Richtung und Sinn geben.\n\nWo sollen wir ihn zuerst hinschicken?", sourceObjectiveStatus = "unverified-source-field" }
quests[61854] = { id = 61854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Meister Sha'lor", sourceObjective = "Der Wald segnet uns heute, {name}.\n\nMeister Sha'lor sagt, er habe sich von seiner Tortur mit den Gorm ausreichend erholt und würde uns gerne helfen, so gut er kann. Er scheint besonders begierig darauf zu sein, neue Dinge zu lernen.\n\nIch schätze, eine kleine Kostprobe eines Abenteuers würde lange vorhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61855] = { id = 61855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Qadarin", sourceObjective = "Schön, Euch wiederzusehen, {name}.\n\nEuer anhaltender Einsatz für das Wohlergehen des Ardenwalds ist nicht unbemerkt geblieben.\n\nQadarin hat Interesse an einer aktiveren Rolle bekundet. Wir sollten seine Fähigkeiten nutzen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[61856] = { id = 61856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Behüterin Vesperblüte", sourceObjective = "Ich habe einen ganz besonderen Segen für Euch, Champion des Ardenwalds. Seid Ihr bereit?\n\nDie Person, die sich heute unserer Jagd anschließt... bin ich!\n\n<Vesperblüte reibt sich grinsend die Hände.>\n\nEs wird schön sein, im Außeneinsatz zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[61857] = { id = 61857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Groonoomcrooek", sourceObjective = "{name}, Eure Hingabe an den Ardenwald und die Königin steht außer Frage.\n\nIrgendetwas, das Ihr getan habt, scheint Groonoomcrooek zufriedengestellt zu haben. Ich weiß allerdings nicht genau, was es war.\n\nEs hat eine Weile gedauert, bis sie mir gesagt hat, dass sie sich uns hier anschließen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[61859] = { id = 61859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Nemea", sourceObjective = "Es ist schön, Euch wiederzusehen, {name}.\n\nEine Freundin von Euch hat freundlicherweise angeboten, uns hier zu unterstützen: Nemea, die Larionmeisterin. Sie wird eine mächtige Verbündete abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[61860] = { id = 61860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Pelodis", sourceObjective = "Es ist schön, Euch wiederzusehen, {name}.\n\nEin Freund von Euch hat freundlicherweise angeboten, uns hier zu unterstützen: Pelodis, der Phalynxmeister. Er wird einen mächtigen Verbündeten abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[61861] = { id = 61861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Sika", sourceObjective = "Wir scheinen eine weitere Rekrutin zu haben, {name}.\n\nSika hat angeboten, uns hier zu helfen, wenn sie mal nicht ihren Pflichten an der Ewigen Schmiede nachkommen muss.\n\nUnterschätzt ihren Wert als Verbündete nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[61862] = { id = 61862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Clora", sourceObjective = "{name}, kann ich Euch kurz sprechen?\n\nEine der kürzlich Aufgestiegenen, Clora, ist davon überzeugt, dass Ihre außergewöhnlichen Kampffertigkeiten unserer Sache dienlich sein würden. Und ich bin geneigt, ihr darin zuzustimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61863] = { id = 61863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Apolon", sourceObjective = "Hallo, mein sterblicher Freund! Ich habe heute gute Neuigkeiten für Euch.\n\nApolon hat mir im Brustton der Überzeugung erzählt, dass der Pfad, dem er folgt, mit dem Euren verwoben sei.\n\nEr hat zwar auch Pflichten gegenüber dem Pfad des Aufstiegs, aber seine Tapferkeit würde uns auch hier eine große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61864] = { id = 61864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Bron", sourceObjective = "Mikanikos hat einen guten Vorschlag gemacht, {name}.\n\nWenn Bron Euch nicht direkt im Feld hilft, könnte er an anderer Stelle in den Schattenlanden seine Dienste leisten.\n\nIch bin mir sicher, dass es Bron nichts ausmachen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[61865] = { id = 61865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Jünger Kosmas", sourceObjective = "Euer Einsatz für die Bastion ist vorbildlich, {name}.\n\nDank der Anima, die Ihr uns zurückgebracht habt, fühlt sich der Jünger Kosmas in der Lage, den Tempel der Reinheit für eine Weile zu verlassen.\n\nEr hat angeboten, uns hier in der Feste zu helfen und sich in den Dienst der Schattenlande zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
